L3_1.m_Face = "UNIT_IDLE"
L3_1.m_CharStrID = "MIYA_HB_NULL_NULL"
L3_1.m_Pos = "C"
L3_1.m_Crash = 10
L3_1.m_Talk_KOREA = "오늘은…… 하트베리 멤버들이랑 다 같이 그라운드 원 번화가에 쇼핑을 나왔는데요."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "今日は……ハートベリーのみんなとグラウンド・ワンの繫華街に買い物に来ました。"
L3_1.m_Talk_ENG = "I’m now in the Ground One downtown, shopping with HRT Berry members."
L3_1.m_Talk_TWN = "我今天……和愛心莓果的成員們一起到G1的鬧區來逛街～"
L3_1.m_Talk_THA = "ตอนนี้ฉันอยู่ที่ดาวน์ทาวน์เขตกราวด์วัน มาช็อปกับสมาชิก HRT เบอร์รี่"
L3_1.m_Talk_VTN = "Mình hiện đang ở trung tâm thành phố Ground One, mua sắm với các thành viên của HRT Berry."
L3_1.m_Talk_SCN = "今天……我跟爱心莓果的其他成员们一起来逛G1繁华的购物街啦。"
L3_1.m_Talk_DEU = "Ich bin jetzt im Ground One in der Innenstadt und kaufe mit HRT Berry-Mitgliedern ein."
L3_1.m_Talk_FRA = "Aujourd'hui, je suis venue faire du shopping au Site n°1 avec les autres filles de HRT Berry."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "SUMMER2021_ACT1_PROLOGUE@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 3200101
L4_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_SURPRISE"
L4_1.m_CharStrID = "MIYA_HB_NULL_NULL"
L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "보시는 것처럼 너무너무 더워요. 어젯밤에도 열대야 때문에 다들 잠자기 힘드셨죠?"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "ご覧のとおりすっごーく暑いです。昨日も熱帯夜のせいでみんな寝苦しかったでしょう？"
L4_1.m_Talk_ENG = "As you can see, it’s super hot today. I’m sure you all suffered through the tropical night yesterday."
L4_1.m_Talk_TWN = "天氣真的好熱喔～ 昨天晚上大家應該也都熱到睡不著吧？"
L4_1.m_Talk_THA = "อย่างที่เห็นนะคะ วันนี้ร้อนสุดๆ ไปเลย ฉันเชื่อว่าทุกคนคงทารมานกับคืนอันร้อนอบอ้าวที่ผ่านมาของเมื่อวานแน่เลย"
L4_1.m_Talk_VTN = "Như các bạn có thể thấy, hôm nay trời rất nóng. Mình chắc rằng tất cả các bạn đã trải nghiệm cái nóng khắc nghiệt của đêm nhiệt đới vào hôm qua."
L4_1.m_Talk_SCN = "如大家所见，这里实在太热了。昨晚大家也都因为闷热而难以入眠吧？"
L4_1.m_Talk_DEU = "Wie ihr sehen könnt, ist es heute superheiß. Ich bin sicher, ihr habt gestern alle unter der Tropennacht gelitten."
L4_1.m_Talk_FRA = "Comme vous pouvez le voir, il fait super chaud ! La nuit tropicale d'hier a été dure, pour vous aussi ?"
