L7_1.m_Crash = 15
L7_1.m_Talk_KOREA = "도시가 전부 찜통이다냥…… 온몸이 땀투성이다냥……"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "都市中が熱湯風呂みたいだにゃ……全身汗だくだにゃあ……"
L7_1.m_Talk_ENG = "The whole city is bwoiling... I’m sweating all owver..."
L7_1.m_Talk_TWN = "整個城市像個烤爐一樣喵……身上都是汗喵……"
L7_1.m_Talk_THA = "ทั้งเมืองกำลังเดือดปุดๆ... ฉันเหงื่อท่วมตัวแล้วละ"
L7_1.m_Talk_VTN = "Cả thành phố như sôi lên... Mình thì đang toát mồ hôi như mưa..."
L7_1.m_Talk_SCN = "整个城市都是大蒸笼……浑身都是汗……"
L7_1.m_Talk_DEU = "Die ganze Stadt glüht in der Hitze ... ich schwitze überall ..."
L7_1.m_Talk_FRA = "Il fait chaud comme dans un four, ici... Je transpire de partout, miaou..."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "SUMMER2021_ACT1_PROLOGUE@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 3200101
L8_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "RUMI_HB_NULL_NULL"
L8_1.m_Pos = "L"
L8_1.m_Talk_KOREA = "매니저, 이런 여름엔 수영장이나 워터 파크가 방송 아이템으로 제격 아냐?"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "マネージャー、こんな夏にはプールやウォーターパークで配信したほうがウケやすいんじゃない？"
L8_1.m_Talk_ENG = "Manager, don’t you think going to a swimming pool or a water park would have worked better in this weather?"
L8_1.m_Talk_TWN = "經紀人！你沒聽過一首歌嗎？每到夏天我要去海邊～～"
L8_1.m_Talk_THA = "ผู้จัดการคะ คุณไม่คิดเหรอว่าการไปสระว่ายน้ำหรือสวนน้ำจะช่วยให้อะไรดีขึ้นในสภาพอากาศแบบนี้?"
L8_1.m_Talk_VTN = "Quản lý, thời tiết này phải đến bể bơi hay công viên nước chứ?"
L8_1.m_Talk_SCN = "经理，这样炎热的夏天，用游泳馆或水上乐园相关的东西当节目道具正合适吧？"
L8_1.m_Talk_DEU = "Manager, glaubst du nicht, dass es bei diesem Wetter besser gewesen wäre, in ein Schwimmbad oder einen Wasserpark zu gehen?"
L8_1.m_Talk_FRA = "Hé, Manager ! On aurait mieux fait d'aller à la piscine ou dans un parc aquatique avec ce temps, vous croyez pas ?"
