L9_1.m_Crash = 20
L9_1.m_Talk_KOREA = "튜브 위에서 줄다리기나 누구 수영복이 제일 섹시한지 투표 받거나!"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "チューブの上で綱引きしたり、誰の水着が一番セクシーなのか投票したりね！"
L9_1.m_Talk_ENG = "We could have played tug of war on swim rings, or had people vote for the sexiest swimsuit."
L9_1.m_Talk_TWN = "至少也要比個沙灘排球，或是投票看誰的泳裝最性感吧？"
L9_1.m_Talk_THA = "เราเล่นชักเย่อบนห่วงยางได้ หรือให้คนโหวตชุดว่ายน้ำที่เซ็กซี่ที่สุดก็ได้นะคะ"
L9_1.m_Talk_VTN = "Chúng ta có thể mặc phao bơi chơi kéo co, hoặc cho mọi người bình chọn xem đâu là bộ đồ bơi sẹc xi nhất."
L9_1.m_Talk_SCN = "可以套着游泳圈拔河，还可以让大家来投票评选最佳泳装！"
L9_1.m_Talk_DEU = "Wir hätten Tauziehen auf Schwimmringen spielen oder die Leute für den sexyesten Bikini stimmen lassen können."
L9_1.m_Talk_FRA = "On aurait pu jouer à la guerre des bouées, ou organiser un vote pour le maillot de bain le plus sexy !"
