L12_1.m_Talk_KOREA = "그만둬. 거기서 더 벗으면 너무 파렴치해."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "やめたほうがいいよ。それ以上の露出は下品に見えるから。"
L12_1.m_Talk_ENG = "Stop it. You can’t take off any more clothes, shame on you."
L12_1.m_Talk_TWN = "可以了，怕人家不知道你愛露嗎？"
L12_1.m_Talk_THA = "พอเถอะ เธอไม่มีเสื้อผ้าให้ถอดมากกว่านี้แล้วนะ น่าอายจริงๆ"
L12_1.m_Talk_VTN = "Dừng lại đi. Cô không thể cởi thêm đồ nữa, thật xấu hổ."
L12_1.m_Talk_SCN = "你快停下，再脱下去就太恬不知耻了。"
