L15_1.m_Pos = "R_M_I"
L15_1.m_Talk_KOREA = "누구더러 파렴치래. 자기는 달밤에 바니걸 복장으로 뛰어다니다 해외 토픽 올랐으면서."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "どの口で下品とかいうわけ？　そんなユキは真夜中にバニーガールコスプレで走り回って海外でもニュースになったでしょ。"
L15_1.m_Talk_ENG = "Shame on you yourself. You ran around in a bunny girl suit in the middle of the night and the whole scene went viral."
L15_1.m_Talk_TWN = "你說誰愛露？不知道是誰穿著兔女郎的衣服到處跑，結果還登上國外頭條呢？"
L15_1.m_Talk_THA = "เธอสิน่าอาย เธอสวมชุดบันนี่วิ่งไปมาตลอดคืนจนคนแชร์วิดีโอกันให้ว่อนไปแล้ว"
L15_1.m_Talk_VTN = "Cô nên tự cảm thấy xấu hổ đi. Cô chạy loanh quanh trong bộ đồ cô gái thỏ vào giữa đêm và toàn bộ cảnh đó đã nổi khắp nơi rồi."
L15_1.m_Talk_SCN = "你说谁恬不知耻呢。半夜里穿着兔女郎装到处跑，在外网上热搜的人是谁啊。"
L15_1.m_Talk_DEU = "Schäm dich selbst. Du bist mitten in der Nacht in einem Bunny Girl-Kostüm herumgelaufen und die ganze Szene wurde viral."
L15_1.m_Talk_FRA = "Honte ? C'est pas moi qui ai déambulé toute la nuit en costume de lapin ! La vidéo est devenue virale, vous avez oublié ?"
