L20_1 = {}
L20_1.m_CutScenKey_Talk = "SUMMER2021_ACT1_PROLOGUE@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 3200101
L20_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SERIOUS"
L20_1.m_CharStrID = "MIYA_HB_NULL_NULL"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "지금 실외 온도는 섭씨 38도래요. 오늘부터 전사 휴무인 태스크포스 컴퍼니도 많다네요."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "現在の外気温は38℃だそうです。今日から臨時休業のタスクフォースカンパニーも多いみたいですね。"
L20_1.m_Talk_ENG = "The outside temperature is 38 Celsius. I heard several TASKFORCE companies shut down operations today."
L20_1.m_Talk_TWN = "聽說現在室外溫度達到攝氏38度，有很多特遣勢力公司今天開始放假呢～"
L20_1.m_Talk_THA = "อุณหภูมิข้างนอกคือ 38 องศาเซลเซียส ได้ยินว่าบริษัททาสก์ฟอร์สหลายแห่งงดปฏิบัติการวันนี้"
L20_1.m_Talk_VTN = "Nhiệt độ bên ngoài là 38°C. Mình nghe nói nhiều công ty TASKFORCE đã ngừng tác chiến hôm nay."
L20_1.m_Talk_SCN = "现在室外温度是38摄氏度。听说有好多特遣势力公司都是从今天开始全公司放假呢。"
L20_1.m_Talk_DEU = "Die Außentemperatur beträgt 38 Grad Celsius. Ich habe gehört, dass mehrere TASKFORCE-Firmen ab heute Betriebsurlaub hätten."
L20_1.m_Talk_FRA = "La température extérieure actuelle est de 38 °C. Il paraît qu'à partir d'aujourd'hui, plusieurs TASKFORCE sont au repos."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "SUMMER2021_ACT1_PROLOGUE@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 3200101
L21_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_LAUGH"
L21_1.m_CharStrID = "MIYA_HB_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "그러니까 우리 시청자 여러분들은 외출할 때는 물병 챙기고 그늘 밑으로 다니기. 미야랑 꼭꼭 약속~"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "なので、視聴者の皆さんも外出する時はこまめな水分補給と、なるべく日陰を歩いてくださいね。ミヤと約束ですよ～！"
L21_1.m_Talk_ENG = "So everyone, make sure to bring water bottles with you, and stay in the shade. It’s a promise with Miya!"
L21_1.m_Talk_TWN = "觀眾們～出門在外記得要多喝水，盡量走在陽光曬不到的地方喔，打勾勾～"
L21_1.m_Talk_THA = "ทุกคนอย่าลืมพกขวดน้ำติดตัวและอยู่ในที่ร่มด้วยล่ะ ต้องสัญญากับมียานะ!"
L21_1.m_Talk_VTN = "Thế nên mọi người hãy đảm bảo là mang theo chai nước và đứng trong bóng râm. Nhớ nhé!"
L21_1.m_Talk_SCN = "所以，亲爱的观众朋友们，大家外出时也一定要带好水杯，在阴凉处行走哦。跟米娅拉钩钩~"
L21_1.m_Talk_DEU = "Habt also immer Wasserflaschen bei euch und bleibt im Schatten. Versprecht es mir!"
L21_1.m_Talk_FRA = "Alors tout le monde, assurez-vous d'avoir toujours une bouteille d'eau avec vous et restez à l'ombre. Promis ?"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "SUMMER2021_ACT1_PROLOGUE@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 3200101
L22_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_SURPRISE"
L22_1.m_CharStrID = "MIYA_HB_NULL_NULL"
L22_1.m_Pos = "C"
L22_1.m_Crash = 20
L22_1.m_Talk_KOREA = "네? 나갈 일 없다고요? 하으, 그, 그런 뜻이 아니라요……"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "え？　そもそもお出かけしない？　ふえぇ、そういう意味じゃなくて……"
L22_1.m_Talk_ENG = "What? You’re not going outside because you don’t have any friends? Aww... That was not what I meant..."
L22_1.m_Talk_TWN = "嗯？沒有要出門喔？欸，我的意思是……"
L22_1.m_Talk_THA = "ว่าไงนะคะ? จะไม่ออกจากบ้านเพราะไม่มีเพื่อนเหรอ? โธ่... ฉันไม่ได้หมายความว่าอย่างนั้นนะ..."
L22_1.m_Talk_VTN = "Cái gì? Sẽ không ra ngoài vì không có bạn ư? Aww... Ý mình không phải vậy..."
L22_1.m_Talk_SCN = "啊？不会外出？哈呃，我、我不是那个意思……"
L22_1.m_Talk_DEU = "Was? Ihr geht nicht raus, weil ihr keine Freunde habt? Oooch ... darauf wollte ich nicht hinaus ..."
L22_1.m_Talk_FRA = "Quoi ? Vous ne sortez pas parce que vous n'avez pas d'amis ? Ah, euh... C'est pas ce que je voulais dire..."
