L26_1.m_CharStrID = "GAEUN_HB_NULL_NULL"
L26_1.m_Talk_KOREA = "<color=#ffd34c>그러면 더우니까 여기서 방종하고 숙소로 복귀할게요. 안녕.</color>"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "<color=#ffd34c>それでは、暑いのでこの辺で配信を終了して、寮に戻りますね。バイバーイ。</color>"
L26_1.m_Talk_ENG = "<color=#ffd34c>Well, it’s too hot to go on, so we’re ending the show now. Byebye.</color>"
L26_1.m_Talk_TWN = "<color=#ffd34c>天氣太熱，今天的直播到此為止，我要回宿舍囉！掰掰～</color>"
L26_1.m_Talk_THA = "<color=#ffd34c>ตอนนี้ร้อนเกินกว่าจะถ่ายทำต่อแล้ว เราขอจบรายการแต่เพียงเท่านี้ บ๊ายบาย</color>"
L26_1.m_Talk_VTN = "<color=#ffd34c>Chà, trời nóng quá rồi không tiếp tục được nữa, nên chúng mình xin kết thúc chương trình tại đây. Tạm biệt mọi người!</color>"
L26_1.m_Talk_SCN = "<color=#ffd34c>天气太热，所以直播就先到这里了，我们要回住处了，拜拜。</color>"
L26_1.m_Talk_DEU = "<color=#ffd34c>Okay, es ist zu heiß, um weiterzumachen, also beenden wir den Livestream jetzt. Ciao!</color>"
L26_1.m_Talk_FRA = "<color=#ffd34c> En tout cas il fait trop chaud pour continuer le stream, alors on arrête ici. Bye !</color>"
