L29_1 = "<color=#ffd34c>B-but guys, it’s only been three minutes!</color>"
L28_1.m_Talk_ENG = L29_1
L29_1 = "<color=#ffd34c>大…大家，我們的直播從開始到現在，錄不到3分鐘欸！</color>"
L28_1.m_Talk_TWN = L29_1
L29_1 = "<color=#ffd34c>ตะ-แต่ว่านี่เพิ่งผ่านมาสามนาทีเองนะ!</color>"
L28_1.m_Talk_THA = L29_1
L29_1 = "<color=#ffd34c>Ơ, ơ kìa mới được ba phút thôi mà!</color>"
L28_1.m_Talk_VTN = L29_1
L29_1 = "<color=#ffd34c>喂、喂！我们刚开直播还不到三分钟呐！</color>"
L28_1.m_Talk_SCN = L29_1
L29_1 = "<color=#ffd34c>A-aber Leute, es sind erst drei Minuten vergangen!</color>"
L28_1.m_Talk_DEU = L29_1
