L34_1.m_Talk_ENG = L35_1
L35_1 = "奇怪……我不是關掉後才去睡的嗎……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "แปลกจัง... ฉันว่าฉันปิดมันก่อนเข้านอนแล้วนะ..."
L34_1.m_Talk_THA = L35_1
L35_1 = "Lạ thật... Mình khá chắc là mình đã tắt nó trước khi đi ngủ mà..."
L34_1.m_Talk_VTN = L35_1
L35_1 = "奇怪……我昨天睡觉前明明关掉了啊……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Das ist seltsam ... Ich bin sicher, ich habe es ausgeschaltet, bevor ich ins Bett gegangen bin ..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "C'est bizarre... Je suis pourtant sûre de l'avoir coupé avant d'aller me coucher..."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
