L37_1 = "SUMMER2021_ACT1_PROLOGUE@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3200101
L36_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "CUTSCENE_TALK_03"
L36_1.m_StartBGMFileName = L37_1
L37_1 = "USER_ADMIN_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "이런, 소리를 조금만 키운다는 게 그만 깨워 버렸군."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "おっと、ちょっとだけ音量を上げるつもりが起こしてしまったか。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Oops, I just wanted to turn the volume up a bit, I didn’t mean to wake you up."
L36_1.m_Talk_ENG = L37_1
L37_1 = "哎呀～一點點聲音就把你吵醒了嗎？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "อ๊ะ ผมแค่อยากจะเปิดเสียงให้ดังขึ้นอีกหน่อย ไม่ได้ตั้งใจจะปลุกคุณนะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ối, tôi chỉ muốn tăng âm lượng một chút thôi, tôi không cố ý đánh thức cô đâu."
L36_1.m_Talk_VTN = L37_1
L37_1 = "啊，稍微调高了一下音量，没想到还是吵醒你了。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hoppla, ich wollte nur die Lautstärke etwas erhöhen, und nicht dich aufwecken."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Oh, je ne voulais pas te réveiller. J'essayais juste d'augmenter un peu le volume."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "SUMMER2021_ACT1_PROLOGUE@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3200101
L37_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "USER_ADMIN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "곤히 자는데 미안하네, 부사장."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ぐっすり寝ていたところすまないな、副社長。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I’m sorry, Vice President."
L37_1.m_Talk_ENG = L38_1
L38_1 = "吵醒你真不好意啊，副總。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ขอโทษทีนะ รองประธาน"
L37_1.m_Talk_THA = L38_1
L38_1 = "Xin lỗi nhé, Phó Chủ Tịch."
L37_1.m_Talk_VTN = L38_1
L38_1 = "打扰你睡觉了，抱歉哈，副总。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Es tut mir leid, Vizepräsidentin."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Désolé, vice-présidente."
L37_1.m_Talk_FRA = L38_1
