L42_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L41_1.m_StartFXSoundName = L42_1
L42_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "음……? 감히 내 침실에 무단 침입해?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "は……？　私の寝室に無断侵入した命知らずがいるの？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Huh? How dare you sneak into my bedroom."
L41_1.m_Talk_ENG = L42_1
L42_1 = "嗯……？你竟敢擅闖我的香閨？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "หืม? กล้าดียังไงถึงแอบเข้ามาในห้องนอนฉัน"
L41_1.m_Talk_THA = L42_1
L42_1 = "Hử? Sao ngươi dám lẻn vào phòng ngủ của ta?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "嗯……？竟然擅自进入我的卧室？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Hä? Wer wagt es, sich in mein Schlafzimmer zu schleichen?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mmh...? Qui ose rentrer dans ma chambre ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
