L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3200101
L42_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
