L43_1 = "m_fFlashBangTime"
L44_1 = 0.35
L42_1[L43_1] = L44_1
L43_1 = "FX_CUTSCEN_SYS_START1"
L42_1.m_StartFXSoundName = L43_1
L43_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "어떤 놈인지 몰라도 살아 나갈 생각은 없겠지?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "誰だか知らないが、生きて帰れると思うな！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Whoever you are, get ready to say goodbye to your life!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "雖然我不知道你是誰，但你別想活著走出去！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ไม่ว่าแกจะเป็นใครก็ตาม เตรียมตัวบอกลาชีวิตได้เลย!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cho dù ngươi là ai, hãy nói lời vĩnh biệt cuộc sống đi!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "虽然不知道你是谁，不过你休想活着离开！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wer auch immer du bist, du kommst hier nicht lebend wieder raus!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Qui que tu sois, ce jour sera ton dernier !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
