L45_1 = "SUMMER2021_ACT1_PROLOGUE@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3200101
L44_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "USER_ADMIN_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "나일세. 그러니까 그 리액티브 소드는 좀 내려 두고 말하게나."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "私だ。だからそのリアクティブソードはしまってくれ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "It’s me. Please put down the Reactive Sword."
L44_1.m_Talk_ENG = L45_1
L45_1 = "是我啦！先把你手上的反應劍放下再說！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "นี่ผมเอง วางดาบต้านปฏิกิริยาลงก่อนนะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Là tôi đây. Hạ Thanh Gươm Tái Tạo xuống đi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "是我。那个，你先把激活的反应剑放下再说。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich bin es. Bitte legen Sie das Reaktive Schwert ab."
L44_1.m_Talk_DEU = L45_1
L45_1 = "C'est moi. Tu veux bien reposer ton épée réactive ?"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "SUMMER2021_ACT1_PROLOGUE@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
