L46_1 = {}
L47_1 = "SUMMER2021_ACT1_PROLOGUE@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3200101
L46_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "무슨 일이시죠? 분명 오늘부터 전사 휴무니 푹 쉬고 오라고 하셨을 텐데요?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "どうしましたか？　確か今日は全社休業だからゆっくり休んでこいと聞いたはずですが。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "What are you doing here? You told me that we’re all off work today."
L46_1.m_Talk_ENG = L47_1
L47_1 = "有什麼事嗎？不是你自己說從今天開始全公司放假嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "คุณมาทำอะไรที่นี่? คุณบอกฉันเองว่าวันนี้เราไม่ทำงาน"
L46_1.m_Talk_THA = L47_1
L47_1 = "Anh đang làm gì ở đây? Anh bảo với tôi là hôm nay tất cả mọi người đều được nghỉ làm mà."
L46_1.m_Talk_VTN = L47_1
L47_1 = "您有什么事吗？您不是说从今天开始全公司放假，让我好好休息吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Was machen Sie hier? Sie haben uns gesagt, dass wir heute Betriebsurlaub haben."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Que faites-vous ici ? Je croyais que c'était congé général aujourd'hui."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "SUMMER2021_ACT1_PROLOGUE@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3200101
L47_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "USER_ADMIN_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "아침에 약한 자네의 귀여운 코맹맹이 소리를 듣고 싶어져서 말이야."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "朝に弱い君の可愛い鼻声が無性に聞きたくなってな。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I just wanted to hear your twang."
L47_1.m_Talk_ENG = L48_1
L48_1 = "就早上突然有點想念你可愛的打呼聲嘛～"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ผมแค่อยากได้ยินเสียงดาบของคุณน่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi chỉ muốn nghe giọng của cô thôi."
L47_1.m_Talk_VTN = L48_1
L48_1 = "我就是想听听你早晨起床后发出的那软绵绵的可爱鼻音。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich wollte Sie nur niedlich plappern hören."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je voulais juste entendre ta respiration au réveil, ce léger ronflement me fait craquer."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "SUMMER2021_ACT1_PROLOGUE@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3200101
L48_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "죽고 싶다는 말을 이상하게 돌려서 하시는군요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "それはあの世に逝きたいという意思表明の新しい言い回しですね。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Was that your death wish?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "你以為加上可愛我就不會打死你嗎？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "นี่คือคำขอก่อนตายเหรอคะ?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đó là lời trăn trối của anh hả?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "您这是转着圈说自己想找死呢。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "War das Ihr Todeswunsch?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Vous voulez mourir ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
