L49_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "어쨌든 알겠습니다. 충성스런 부하직원으로서 기꺼이 그 길고 한심한 인생을 끝내드리죠."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "とにかくわかりました。忠誠心が高い部下として、喜んでその長きに渡る情けない人生を終わらせてあげましょう。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I understand. As your loyal employee, I will gladly end your long and pathetic life."
L49_1.m_Talk_ENG = L50_1
L50_1 = "沒問題！身為一位忠心的職員，既然老闆這麼想死，我只好恭敬不如從命！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฉันเข้าใจนะคะ ในฐานะพนักงานที่ภักดี ฉันยินดีจบชีวิตอันยืดยาวและน่าสังเวชของคุณค่ะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi hiểu rồi. Là một nhân viên trung thành, tôi sẽ vui lòng kết thúc cuộc đời dài dòng và thảm hại của anh."
L49_1.m_Talk_VTN = L50_1
L50_1 = "了解了。作为忠诚的下属，我很乐意结束您那漫长又荒唐的人生。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich verstehe. Als Ihr treue Mitarbeiterin werde ich gerne Ihr langes und erbärmliches Leben beenden."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je comprends. En tant que votre employée la plus fidèle, je me ferai un plaisir de mettre fin à votre longue et pathétique vie."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "SUMMER2021_ACT1_PROLOGUE@50#Talk"
