L52_1 = 0.72
L50_1[L51_1] = L52_1
L51_1 = "USER_ADMIN_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "농담일세, 농담! 그 칼 좀 저리 치우게나!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "冗談だ、冗談！　だからその剣をしまってくれ！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "That was a joke! A joke! Please put away that sword!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "開玩笑的啦～沒事沒事！快把刀放下！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "พูดเล่นน่า! มุกน่ะ! เอาดาบไปไกลๆ ด้วย!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Đó là một trò đùa thôi! Một trò đùa thôi! Làm ơn hãy cất thanh kiếm đó đi!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "我开玩笑的，开个玩笑！你快把剑收起来！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Das war ein Witz! Ein Witz! Bitte stecken Sie das Schwert weg!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "C'était une blague ! Une blague ! Range ton épée, tu veux bien ?"
L50_1.m_Talk_FRA = L51_1
