L4_1 = "USER_ADMIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "실은 어제 전사 휴무를 공지한 뒤에 하나 양이 그러더군."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "実は昨日、全社休業を告知した後に管理部長からある話を聞いてな。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Yesterday, Hana told me something after the day-off announcement."
L3_1.m_Talk_ENG = L4_1
L4_1 = "事情是這樣的，昨天宣布全公司放假後，荷娜跟我說…"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เมื่อวานฮานามาคุยกับผมหลังประกาศวันหยุด"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hôm qua, Hana đã nói với tôi một vài chuyện sau thông báo ngày nghỉ."
L3_1.m_Talk_VTN = L4_1
L4_1 = "其实是昨天通知完全公司放假后，千夜提醒我的。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Gestern hat mir Hana nach der Ankündigung des Betriebsurlaubs etwas erzählt."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Hier, Hana est venue me voir après mon annonce."
L3_1.m_Talk_FRA = L4_1
