L6_1 = "SUMMER2021_ACT1_PROLOGUE@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3200101
L5_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_LAUGH"
L6_1 = "KIMHANA_COFFIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "R"
L6_1 = "후후, 전사 휴무는 오랜만이네요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "フフ、全社休業は久しぶりですね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Oh, it’s been a while since the whole company got a day off."
L5_1.m_Talk_ENG = L6_1
L6_1 = "哇～好久沒有全公司放假囉？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "บริษัทไม่มีวันหยุดมานานแล้วนะคะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Đã rất lâu rồi từ khi cả công ty được nghỉ một ngày."
L5_1.m_Talk_VTN = L6_1
L6_1 = "嘿嘿，好久没全公司放假了呢。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Oh, es ist schon eine Weile her, dass wir einen Betriebsurlaub hatten."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Oh, ça fait un moment qu'on a pas eu de congé général à l'entreprise !"
L5_1.m_Talk_FRA = L6_1
