L7_1 = "SUMMER2021_ACT1_PROLOGUE@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3200101
L6_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "L"
L7_1 = "음? 작년에는 전사 휴무를 안 했나?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "うん？　去年は全社休業がなかったのか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Hm? There was no day-off last year?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "是嗎？公司去年沒放嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "หืม? ปีที่แล้วไม่มีวันหยุดเหรอ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Hử? Năm ngoài không có ngày nghỉ nào à?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "嗯？去年没全公司放假吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Hm? Gab es letztes Jahr keinen Betriebsurlaub?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Hmm ? Il n'y en a pas eu l'année dernière ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "SUMMER2021_ACT1_PROLOGUE@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3200101
L7_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "L"
L8_1 = "그라운드 원은 대균열 때문에 이상 기후가 심해서 도시관리국도 권장하고 있을 텐데?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "グラウンド・ワンは大亀裂のせいで異常気象が激しいから、都市管理局も推奨していたはずなんだが。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "City Management recommends companies to have day-offs, as Ground One suffers several weather anomalies due to the Grand Dimension Crevice."
L7_1.m_Talk_ENG = L8_1
L8_1 = "G1因為大峽谷的關係導致氣候嚴重異常，城市管理局應該也有建議要放假吧？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "สำนักบริหารเมืองแนะนำให้บริษัทมีวันหยุด เนื่องจากกราวด์วันประสบปัญหาความผิดปกติทางสภาพอากาศเนื่องจากรอยแยกมิติขนาดมหึมา"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ban Quản Lý Thành Phố khuyến nghị các công ty nên có ngày nghỉ, vì Ground One gặp phải một số bất thường về thời tiết do Khe Nứt Không Gian Vĩ Đại."
L7_1.m_Talk_VTN = L8_1
L8_1 = "受大裂谷影响，G1出现了严重的异常气候，所以城市管理局应该也是建议放假的吧？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Die Stadtverwaltung empfiehlt Unternehmen, Ruhetage einzulegen, da Ground One aufgrund der Dimensionskluft unter Wetteranomalien leidet."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Avec les crevasses de grande dimension que connaît le Site n°1 en ce moment, la Direction des cités devrait plutôt préconiser des jours de congés pour les entreprises, non ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "SUMMER2021_ACT1_PROLOGUE@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3200101
L8_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_DESPAIR"
L9_1 = "KIMHANA_COFFIN_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "R"
L9_1 = "다 같이 며칠씩이나 쉴 만큼 회사 형편이 여유롭진 않았으니까요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "全員で数日休めるほど、会社の財政事情に余裕がありませんでしたので。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Well, we didn’t have the luxury of taking holidays back then."
L8_1.m_Talk_ENG = L9_1
L9_1 = "因為公司的財務狀況，沒辦法讓全公司員工放那麼多天假。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ปฏิบัติการของเราไม่มีสิทธิ์ที่จะได้หยุดพัก"
L8_1.m_Talk_THA = L9_1
L9_1 = "Chà, hoạt động của chúng ta không có những thứ xa xỉ như ngày nghỉ."
L8_1.m_Talk_VTN = L9_1
L9_1 = "是，不过因为公司情况有困难，不允许大家一起连休几天。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Nun, unsere Firma hatte nicht den Luxus, tagelang Urlaub für alle zu erlauben."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Malheureusement, le congé général est un luxe qu'on ne peut pas se permettre."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "SUMMER2021_ACT1_PROLOGUE@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3200101
L9_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "KIMHANA_COFFIN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "R"
L10_1 = "특히 부사장님께서 고생하셨죠. 몇 년간 휴가 한 번 없이 주말에도 나와서 일하셨거든요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "特に副社長がかなり苦労されてましたね。数年間ずっと休みを返上して週末も働いているんです。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Especially the Vice President. She worked 24/7 for years without a single vacation."
L9_1.m_Talk_ENG = L10_1
L10_1 = "尤其是副總超辛苦的！她已經好幾年沒休假，連假日也要辦公。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "โดยเฉพาะรองประธานที่ทำงานทุกวันตลอดปีโดยไม่พักร้อนเลยสักครั้ง"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đặc biệt là Phó Chủ Tịch. Chị ấy làm việc 24/7 hàng năm trời mà chưa từng nghỉ ngơi."
L9_1.m_Talk_VTN = L10_1
L10_1 = "尤其是副总，她真的很辛苦。这几年不仅一次假都没休过，就连周末也在加班。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Vor allem die Vizepräsidentin. Sie hat jahrelang rund um die Uhr gearbeitet, ohne einen einzigen Urlaub."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Et encore moins la vice-présidente. Elle travaille 24 heures sur 24 et 7 jours sur 7 depuis des années, sans un seul jour de repos."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
