L14_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "……하나 씨도 참, 은근히 입이 가볍다니까요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ナカシマさんったら……意外と口が軽いんですね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "... Hana sometimes talks too much."
L13_1.m_Talk_ENG = L14_1
L14_1 = ".荷娜也真是的，沒想到是個大嘴巴。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "...บางครั้งฮานาก็พูดมากนะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "... Đôi lúc Hana nói quá nhiều."
L13_1.m_Talk_VTN = L14_1
L14_1 = "……千夜也真是的，就是嘴快。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Hana redet manchmal zu viel."
L13_1.m_Talk_DEU = L14_1
L14_1 = "... Décidément, Hana ne sait pas garder sa langue."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "SUMMER2021_ACT1_PROLOGUE@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3200101
L14_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "USER_ADMIN_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "뭐, 그래서 자네가 모처럼의 휴가를 근사하게 보내도록 도와 주러 온 걸세."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "まあ、ということで君がせっかくの休みを優雅に過ごせるように手伝いに来たわけさ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Well, I’m here to help you to enjoy your first vacation in years."
L14_1.m_Talk_ENG = L15_1
L15_1 = "嗯，所以我是來幫助你過個難忘的假期的。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ผมก็เลยมาที่นี่เพื่อช่วยให้คุณได้สนุกกับการพักร้อนครั้งแรก"
L14_1.m_Talk_THA = L15_1
L15_1 = "Chà, tôi ở đây để giúp cô tận hưởng kỳ nghỉ đầu tiên."
L14_1.m_Talk_VTN = L15_1
L15_1 = "所以呢，我来找你的目的就是帮你度过美好而宝贵的假期。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Tja, ich bin hier, um Ihnen zu helfen, Ihren ersten Urlaub zu genießen."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Quoi qu'il en soit, je suis ici pour t'aider à profiter de tes premières vacances dignes de ce nom."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "SUMMER2021_ACT1_PROLOGUE@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3200101
L15_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "구체적인 조건을 말씀해 주시면 검토해 보기로 하죠."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "具体的な条件を教えてくれたら、検討します。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Give me the specifics then I’ll go through them."
L15_1.m_Talk_ENG = L16_1
L16_1 = "可以告訴我具體的內容，我會考慮看看。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ระบุมาให้ชัดเจนแล้วฉันจะจัดการค่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cung cấp cho tôi thông tin chi tiết cụ thể sau đó tôi sẽ xem xét."
L15_1.m_Talk_VTN = L16_1
L16_1 = "您先说具体是什么条件，我再来做决定。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Sagen Sie mir die Einzelheiten, dann werde ich sie durchgehen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Très bien, donnez-moi les détails de la mission et je vous dirai ce que je peux faire."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "SUMMER2021_ACT1_PROLOGUE@66#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 66
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3200101
L16_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "USER_ADMIN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "거래에 임할 생각은 있다는 뜻으로 이해되는군."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "取引に応じる可能性はあると受け止めていいんだな。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I see you’re ready to make a deal."
L16_1.m_Talk_ENG = L17_1
L17_1 = "這表示你同意我的提議吧？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "คุณก็พร้อมทำข้อตกลงนี่นา"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi thấy là cô đã sẵn sàng để thỏa thuận rồi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "看来你还是有一点兴趣的嘛。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich sehe, Sie sind bereit, einen Deal einzugehen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Tu parles comme si tu étais prête à conclure un marché."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "SUMMER2021_ACT1_PROLOGUE@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3200101
L17_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "USER_ADMIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "백 번 듣는 것보단 한 번 경험하는 게 낫지. 어서 나갈 준비 하게나."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "百聞は一見に如かず、一度経験したほうがいいだろう。さっそく出かける準備をしよう。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Actions speak louder than words. Let’s get ready to go outside."
L17_1.m_Talk_ENG = L18_1
L18_1 = "百聞不如一見，趕快準備出門吧。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "การกระทำเสียงดังกว่าคำพูด เตรียมตัวออกไปข้างนอกกันเถอะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nói ít làm nhiều nào. Chuẩn bị ra ngoài nào."
L17_1.m_Talk_VTN = L18_1
L18_1 = "不过俗话说，百闻不如一见。你准备一下出门就知道了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Taten sagen mehr als Worte. Machen wir uns bereit, nach draußen zu gehen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Enfin, une action vaut mieux que mille mots. Habille-toi, nous sortons."
L17_1.m_Talk_FRA = L18_1
