L23_1 = "SUMMER2021_ACT1_PROLOGUE@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3200101
L22_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "제가 잠잘 때 옷 입기 싫어한다는 거, 잘 아시지 않습니까?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "私が寝る時は服を着ないことは、よくご存知でしょう。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "You know I don’t wear clothes when I go to bed."
L22_1.m_Talk_ENG = L23_1
L23_1 = "你應該知道我睡覺的時候習慣裸睡吧？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "คุณก็รู้ว่าฉันไม่สวมเสื้อผ้าเวลาเข้านอน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Anh biết đấy, tôi không mặc quần áo khi đi ngủ."
L22_1.m_Talk_VTN = L23_1
L23_1 = "我睡觉的时候不喜欢穿衣服，您应该很清楚这一点吧？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Sie wissen doch, dass ich keine Kleidung trage, wenn ich ins Bett gehe."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Vous savez bien que je ne porte pas de vêtements quand je dors, non ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
