L23_1.m_fTalkTime = 0.03
L24_1 = "ハハハ、もちろんさ。何を今更……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Hah hah, I thought we were close enough to..."
L23_1.m_Talk_ENG = L24_1
L24_1 = "哈哈，大家都這麼熟了，跟我客氣什麼…"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฮ่าๆ ผมนึกว่าเราสนิทกันมากพอซะอีก"
L23_1.m_Talk_THA = L24_1
L24_1 = "Ha ha tôi nghĩ chúng ta đủ thân để..."
L23_1.m_Talk_VTN = L24_1
L24_1 = "哈哈，咱俩谁跟谁呀，有什么不好意思的……"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Haha, ich dachte, wir stünden uns nah genug ..."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Ha ha, je pensais que nous étions assez proches pour..."
