L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "USER_ADMIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "……베개도 자네가 던지니 좀 아프군."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "……君が投げる枕はすごい威力だな。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Even a pillow hurts when you throw it."
L26_1.m_Talk_ENG = L27_1
L27_1 = "…被你扔的枕頭打到還真的有點疼。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "คุณนี่แม้แต่ปาหมอนยังเจ็บเลย"
L26_1.m_Talk_THA = L27_1
L27_1 = "Cô ném một chiếc gối thôi cũng đau."
L26_1.m_Talk_VTN = L27_1
L27_1 = "……轻点啊，你扔的枕头都能砸疼人。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Sogar ein Kissen tut weh, wenn Sie es werfen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "... Entre tes mains, un oreiller est aussi dangereux qu'une épée."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
