L32_1 = "SUMMER2021_ACT1_PROLOGUE@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3200101
L31_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_DESPAIR"
L32_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "그래서, 어디로 데려갈 생각이시죠?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "それで、どこに連れていくつもりですか？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "So, where are you taking me?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "所以，你要帶我去哪裡？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "แล้วคุณจะพาฉันไปไหนคะ?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Được rồi, thế anh định đưa tôi đi đâu?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "所以说，您想带我去哪儿？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Also, wohin bringen Sie mich?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Alors, où m'emmenez-vous ?"
L31_1.m_Talk_FRA = L32_1
