L35_1 = "SUMMER2021_ACT1_PROLOGUE@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3200101
L34_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_PRIDE"
L35_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "R"
L35_1 = "호텔 아르마다로. 옥상에 있는 수영장이 경치가 무척 좋다더군."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ホテルアルマダへ。屋上のプールからの景色が格別だそうだ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "To Hotel Armada. I heard their rooftop pool has a wonderful view."
L34_1.m_Talk_ENG = L35_1
L35_1 = "帶你去艾魯瑪達飯店。聽說頂樓的泳池景色超棒喔！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ไปโรงแรมอาร์มาดา ผมได้ยินว่าสระน้ำบนยอดตึกที่นั่นมีวิวสุดยอดมาก"
L34_1.m_Talk_THA = L35_1
L35_1 = "Đến Khách sạn Armada. Tôi nghe nói hồ bơi trên sân thượng có view rất đỉnh."
L34_1.m_Talk_VTN = L35_1
L35_1 = "去阿曼达酒店。据说那家酒店楼顶上的游泳池景色相当不错。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Zum Hotel Armada. Ich habe gehört, der Pool auf dem Dach habe eine wunderbare Aussicht."
L34_1.m_Talk_DEU = L35_1
L35_1 = "À l'hôtel Armada. J'ai entendu dire qu'il y avait une vue magnifique depuis la piscine sur le toit."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "SUMMER2021_ACT1_PROLOGUE@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3200101
L35_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_SURPRISE"
L36_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "L"
L36_1 = "아르마다라면……. 확실히 며칠 전에 만난 거래처 대표도 무척 호평하더군요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "アルマダなら……確かに数日前に会った取引先の社長も評価していましたね。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Armada... One of our client’s CEO spoke highly of the place a few days ago."
L35_1.m_Talk_ENG = L36_1
L36_1 = "艾魯瑪達嗎… 前幾天見到的客戶代表好像也滿喜歡的。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อาร์มาดา... CEO ของลูกค้ารายหนึ่งของเราเพิ่งกล่าวชมที่นี่เมื่อไม่กี่วันก่อน"
L35_1.m_Talk_THA = L36_1
L36_1 = "Armada... Một trong những CEO khách hàng của chúng ta đã đánh giá rất cao nơi này vài ngày trước đấy."
L35_1.m_Talk_VTN = L36_1
L36_1 = "阿曼达啊……前几天见的客户公司代表也说那里很不错呢。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Armada ... Der CEO einer unserer Kunden hat vor ein paar Tagen den Ort in höchsten Tönen gelobt."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Armada... Un client m'a fait l'éloge de l'endroit, il y a quelques jours."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "SUMMER2021_ACT1_PROLOGUE@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3200101
L36_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "L"
L37_1 = "그런데 거길 언제 예약하셨습니까? 예약 일정은 내년까지 전부 차 있을 텐데요?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ところで、いつ予約したのですか？　あのホテルの予約は来年まで埋まっているはずですが。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "But how? I heard the hotel was fully booked until next year."
L36_1.m_Talk_ENG = L37_1
L37_1 = "不過你什麼時候預訂的？飯店的預約應該到明年都滿了吧？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แต่เป็นไปได้ไงคะ? ฉันได้ยินมาว่าโรงแรมถูกจองเต็มถึงปีหน้าแล้วนี่นา"
L36_1.m_Talk_THA = L37_1
L37_1 = "Nhưng anh đã làm thế nào? Tôi nghe nói khách sạn này đã được đặt trước cho đến năm sau."
L36_1.m_Talk_VTN = L37_1
L37_1 = "不过您什么时候预约的那里？那儿的预约日程应该都排到明年了吧？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Aber wie? Ich dachte, dass das Hotel bis nächstes Jahr ausgebucht sei."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Mais comment avez-vous fait ? J'ai entendu dire que l'hôtel était complet jusqu'à l'année prochaine."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "SUMMER2021_ACT1_PROLOGUE@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3200101
L37_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_DESPAIR"
L38_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "R"
L38_1 = "에헴. 고생하는 부사장을 위해 내가 그 정도도 못 해 주겠나."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "えっへん。苦労している副社長のために、それぐらいできて当然だ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Ahem... I can do anything for my dear hard-working Vice President."
L37_1.m_Talk_ENG = L38_1
L38_1 = "呵呵，為了辛苦工作的副總，區區小事不足掛齒。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อะแฮ่ม... ผมทำได้ทุกอย่างเพื่อรองประธานคนดีที่ทำงานหนักนะครับ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Ahem... Tôi có thể làm mọi thứ cho Phó Chủ Tịch chăm chỉ của mình."
L37_1.m_Talk_VTN = L38_1
L38_1 = "唉嘿。副总为公司呕心沥血，这点小事难道我还做不到吗。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ähem. Ich kann alles für meine liebe, hart arbeitende Vizepräsidentin tun."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ahem... Pour ma vice-présidente adorée, je suis capable de tout."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "SUMMER2021_ACT1_PROLOGUE@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3200101
L38_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_LAUGH"
L39_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "R"
L39_1 = "실은 자네를 위해 그라운드 원의 기상조절 시스템을 살짝 손봐 놓았다네."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "実は君のために、グラウンド・ワンの気象調整システムにちょっとだけ手を加えたのさ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "To tell you the truth, I even tweaked the Ground One Weather Control System a bit for you."
L38_1.m_Talk_ENG = L39_1
L39_1 = "其實我爲了你，還稍微動了G1 的氣象調節系統呢。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "บอกตามตรงนะ ผมถึงขนาดปรับระบบควบคุมสภาพอากาศที่กราวด์วันนิดหน่อยเพื่อคุณด้วย"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nói thật thì, tôi thậm chí đã chỉnh sửa một chút Hệ Thống Kiểm Soát Thời Tiết Ground One vì cô đấy."
L38_1.m_Talk_VTN = L39_1
L39_1 = "那个吧，为了让你好好享受假期，我对G1的气象调节系统稍稍动了一点手脚。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Um die Wahrheit zu sagen, habe ich sogar das Ground One Wetterkontrollsystem ein wenig für Sie optimiert."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Pour vous dire la vérité, j'ai même un peu modifié le système de contrôle météorologique du Site n°1 pour l'occasion."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "SUMMER2021_ACT1_PROLOGUE@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3200101
L39_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_PRIDE"
L40_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "R"
L40_1 = "자, 가지. 좀 덥긴 해도 오늘은 이 도시 역사상 물놀이를 하기 가장 적합한 날씨가 될 거야."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "さあ、出発しよう。少し暑いが、今日はこの都市史上最高に水遊びにピッタリな天気になるはずさ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Let’s go. It’s a bit hot, but today will be the best day to go swimming."
L39_1.m_Talk_ENG = L40_1
L40_1 = "我們走吧！雖然有點熱，但今天會是這個城市史上最適合玩水的天氣喔！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ไปกันเถอะ อากาศร้อนนิดหน่อย แต่วันนี้แหละที่เหมาะกับการว่ายน้ำ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đi thôi. Trời hơi nóng, nhưng hôm nay sẽ là một ngày tuyệt vời để đi bơi."
L39_1.m_Talk_VTN = L40_1
L40_1 = "好啦，走吧。虽然有点热，但今天的天气绝对是这个城市有史以来最适合玩水的一天。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Gehen wir. Es ist ein bisschen heiß, aber heute ist der perfekte Tag zum Schwimmen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Allons-y. Il fait un peu chaud, mais les conditions sont idéales pour aller piquer une tête."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
