L44_1 = "FX_CUTSCEN_BEEP"
L43_1.m_StartFXSoundName = L44_1
L44_1 = "TV1_NPC_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "<color=#ffd34c>속보입니다. 기상조절 시스템의 오작동으로, 현재 그라운드 원의 기온은 섭씨 45도를 웃돌고 있습니다.</color>"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "<color=#ffd34c>速報です。気象調節システムの誤作動で、現在グラウンド・ワンの気温は45℃を超えています。</color>"
L43_1.m_Talk_JPN = L44_1
L44_1 = "<color=#ffd34c>This just in. Due to the Weather Control System malfunction, the current temperature of Ground One has now reached 45 Celsius.</color>"
L43_1.m_Talk_ENG = L44_1
L44_1 = "<color=#ffd34c>快報！由於氣象調節系統故障，現在 G1 的氣溫已經超過攝氏45度。</color>"
L43_1.m_Talk_TWN = L44_1
L44_1 = "<color=#ffd34c>ข่าวด่วน เนื่องจากความผิดปกติของระบบควบคุมสภาพอากาศ อุณหภูมิปัจจุบันของกราวด์วันพุ่งขึ้นมาอยู่ที่ 45 องศาเซีลเซียสแล้ว</color>"
L43_1.m_Talk_THA = L44_1
L44_1 = "<color=#ffd34c>Tin vừa nhận. Do lỗi của Hệ Thống Kiểm Soát Thời Tiết, nhiệt độ hiện tại của Ground One đã đạt 45°C.</color>"
L43_1.m_Talk_VTN = L44_1
L44_1 = "<color=#ffd34c>现在播报快讯。因气象调节系统发生故障，目前G1的气温已超过45摄氏度。</color>"
L43_1.m_Talk_SCN = L44_1
L44_1 = "<color=#ffd34c>Eilnachrichten. Aufgrund der Fehlfunktion des Wetterkontrollsystems hat die aktuelle Temperatur von Ground One jetzt 45 Grad Celsius erreicht.</color>"
L43_1.m_Talk_DEU = L44_1
L44_1 = "<color=#ffd34c>Flash info. En raison d'un dysfonctionnement du système de contrôle météorologique, la température du Site n°1 s'élève actuellement à 45 °C.</color>"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "SUMMER2021_ACT1_PROLOGUE@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3200101
L44_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "TV1_NPC_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "<color=#ffd34c>현장에 나간 기자를 통해 더 자세한 소식 전해 드리겠습니다.</color>"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "<color=#ffd34c>現場のリポーターに繋げて、より詳しくお伝えします。</color>"
L44_1.m_Talk_JPN = L45_1
L45_1 = "<color=#ffd34c>More news from the scene.</color>"
L44_1.m_Talk_ENG = L45_1
L45_1 = "<color=#ffd34c>請特派記者為我們帶來現場消息。</color>"
L44_1.m_Talk_TWN = L45_1
L45_1 = "<color=#ffd34c>ไปดูข่าวเพิ่มเติมจากสถานที่จริงกัน</color>"
L44_1.m_Talk_THA = L45_1
L45_1 = "<color=#ffd34c>Thêm tin tức từ hiện trường.</color>"
L44_1.m_Talk_VTN = L45_1
L45_1 = "<color=#ffd34c>下面由在现场的记者为大家介绍详细情况。</color>"
L44_1.m_Talk_SCN = L45_1
L45_1 = "<color=#ffd34c>Weitere Neuigkeiten berichtet unser Reporter vor Ort.</color>"
L44_1.m_Talk_DEU = L45_1
L45_1 = "<color=#ffd34c>Découvrez le témoignage de notre envoyé spécial sur place.</color>"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
