L47_1 = "TV2_NPC_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "<color=#ffd34c>여기는 도시 관리국 앞입니다! 바깥 날씨는 보시는 것처럼 도로에 놔둔 베이컨이 바짝 익을 정도로……!</color>"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "<color=#ffd34c>こちらは都市管理局の前です！　外の空気はご覧のとおり、道路に乗せたベーコンがカリカリに焼けるぐらいです……！</color>"
L46_1.m_Talk_JPN = L47_1
L47_1 = "<color=#ffd34c>I’m here right in front of City Management! As you can see, I put a piece of bacon on the road, and it fries instantly...</color>"
L46_1.m_Talk_ENG = L47_1
L47_1 = "<color=#ffd34c>這裡是城市管理局前門！如大家所見，外面的天氣熱到可以煎雞蛋………！</color>"
L46_1.m_Talk_TWN = L47_1
L47_1 = "<color=#ffd34c>ที่นี่คือหน้าสำนักบริหารเมือง! อย่างที่คุณเห็น แค่วางเบคอนไว้บนถนน เบคอนก็สุกทันที...</color>"
L46_1.m_Talk_THA = L47_1
L47_1 = "<color=#ffd34c>Tôi đang ở phía trước Ban Quản Lý Thành Phố! Như các bạn có thể thấy, khi tôi đặt miếng thịt xong khói trên đường, nó ngay lập tức bị chiên chín...</color>"
L46_1.m_Talk_VTN = L47_1
L47_1 = "<color=#ffd34c>我这里是城市管理局前面！如大家所见，外面的天气非常热，把培根放到马路上都快要烤熟了……！</color>"
L46_1.m_Talk_SCN = L47_1
L47_1 = "<color=#ffd34c>Live und direkt vor der Stadtverwaltung! Wie Sie sehen können, lege ich einen Speck auf die Straße, und er brät sofort an ...</color>"
L46_1.m_Talk_DEU = L47_1
L47_1 = "<color=#ffd34c>Je suis actuellement en face de la direction des cités et comme vous pouvez le voir, cette tranche de bacon que je viens de poser sur le bitume est déjà cuite... !</color>"
L46_1.m_Talk_FRA = L47_1
