L2_1 = "SUMMER2021_ACT1_PROLOGUE@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3200101
L1_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_LAUGH"
L2_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "L"
L2_1 = "말씀하신 대로 <color=#ffd34c>좀</color> 덥군요. 수영장에 들어갔다간 산 채로 삶아질 정도로요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "おっしゃるとおり<color=#ffd34c>少し</color>暑いですね。プールに入ると生きたまま茹でられるんじゃないかと思うぐらいです。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Like you said, it’s <color=#ffd34c>a bit</color> hot here. Hot enough to boil in a pool."
L1_1.m_Talk_ENG = L2_1
L2_1 = "就像你說的是<color=#ffd34c>有點</color> 熱，跳進泳池應該會被煮熟吧？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "อย่างที่คุณว่า ที่นี่อากาศร้อน<color=#ffd34c>นิดหน่อย</color> ร้อนขนาดที่ถูกต้มในสระว่ายน้ำได้เลย"
L1_1.m_Talk_THA = L2_1
L2_1 = "Như anh nói, ở đây <color=#ffd34c>hơi</color> nóng. Đủ nóng để đun sôi cả hồ bơi."
L1_1.m_Talk_VTN = L2_1
L2_1 = "果真如您所说，<color=#ffd34c>有点儿</color>热呢。进游泳池的话简直就是生煮啊。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wie Sie sagten, ist es hier <color=#ffd34c>ein bisschen</color> heiß. Heiß genug, um im Pool gedünstet zu werden."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Il fait <color=#ffd34c>un peu</color> chaud ici, comme vous dites. Assez chaud pour bouillir dans une piscine."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "SUMMER2021_ACT1_PROLOGUE@102#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 102
