L3_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "L"
L3_1 = "대체 기상조절 시스템에 무슨 짓을 하신 거죠?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "気象調節システムに何をしたのですか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "What have you done to the Weather Control System?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "你到底對氣象調節系統做了什麼？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "คุณทำอะไรกับระบบควบคุมสภาพอากาศคะ?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Anh đã làm gì với Hệ Thống Kiểm Soát Thời Tiết thế?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "您到底对气象调节系统做了什么？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Was haben Sie mit dem Wetterkontrollsystem gemacht?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Qu'avez-vous fait au système de contrôle météorologique ?"
L2_1.m_Talk_FRA = L3_1
