L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L4_1.m_Crash = 15
L5_1 = "이, 이럴 리가 없는데……."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "こ、こんなはずがない……"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Th-this shouldn't be happening..."
L4_1.m_Talk_ENG = L5_1
L5_1 = "怎… 怎麼會這樣… "
L4_1.m_Talk_TWN = L5_1
L5_1 = "มะ-มันไม่น่าจะเป็นแบบนี้นี่นา..."
L4_1.m_Talk_THA = L5_1
L5_1 = "Chuyện này đáng lẽ không nên xảy ra..."
L4_1.m_Talk_VTN = L5_1
L5_1 = "不、不应该啊……"
L4_1.m_Talk_SCN = L5_1
