L5_1.m_Crash = 30
L6_1 = "걱정 말게나! 아르마다는 세계 최고의 호텔 브랜드야!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "心配することはない！　アルマダは世界最高のホテルブランドだ！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Don’t worry! Armada is the best hotel in the world!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "請不要擔心！艾魯瑪達是全世界最好的飯店品牌！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ไม่ต้องห่วงครับ! อาร์มาดาเป็นโรงแรมที่ดีที่สุดในโลก!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Đừng lo! Armada là khách sạn tốt nhất trên thế giới!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "别担心！阿曼达是世界顶级酒店品牌！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Machen Sie sich keine Sorgen! Armada ist das beste Hotel der Welt!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais ne t'inquiète pas, l'Armada est le meilleur hôtel du monde !"
L5_1.m_Talk_FRA = L6_1
