L7_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "R"
L7_1 = "겨우 폭염 따위로 수영장 수온 관리를 실패할 리가……"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "たかが猛暑ぐらいで、プールの水温管理に失敗するはずが……"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I’m sure they can control their pool’s water temperature..."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不可能因為酷暑而導致游泳池水溫管理失敗…"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ผมมั่นใจว่าพวกเขาควบคุมอุณหภูมิของน้ำในสระได้..."
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi chắc là họ có thể kiểm soát nhiệt độ hồ bơi của họ..."
L6_1.m_Talk_VTN = L7_1
L7_1 = "区区水温这种事情，不会因为炎热就……"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich bin mir sicher, dass sie die Wassertemperatur des Pools im Griff haben ..."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je suis sûr qu'ils peuvent contrôler la température de l'eau de leur piscine..."
L6_1.m_Talk_FRA = L7_1
