L11_1 = "STAFF_NPC_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "갑자기 연락 드려 죄송합니다, 손님."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "急な連絡で申し訳ございません、お客様。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Hello, this is Hotel Armada."
L10_1.m_Talk_ENG = L11_1
L11_1 = "客人不好意思，突然打給您。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "สวัสดีค่ะ นี่คือโรงแรมอาร์มาดา"
L10_1.m_Talk_THA = L11_1
L11_1 = "Hello, đây là Khách sạn Armada."
L10_1.m_Talk_VTN = L11_1
L11_1 = "很抱歉突然联系您，客人。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Hallo, hier ist das Hotel Armada."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Bonjour, c'est l'hôtel Armada."
