L12_1 = "SUMMER2021_ACT1_PROLOGUE@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3200101
L11_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "STAFF_NPC_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "실은 방금 전, 차원 함선이 저희 호텔 옥상을 들이받아 모시기 어렵게 되었습니다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "実は先ほど、次元艦船が当ホテルの屋上に衝突し、お迎えすることが難しくなりました。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "As a dimensional ship has crashed on our rooftop, we won’t be in service today. My apologies."
L11_1.m_Talk_ENG = L12_1
L12_1 = "是這樣的，剛才有一艘次元艦船撞到我們飯店的屋頂，恐怕無法再繼續接待您。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ยานข้ามมิติเพิ่งชนเข้ากับดาดฟ้าตึกของเรา วันนี้เราเลยเปิดให้บริการไม่ได้ค่ะ ขออภัยด้วย"
L11_1.m_Talk_THA = L12_1
L12_1 = "Do một chiến hạm đa chiều đã va chạm vào sân thượng nên chúng tôi sẽ không hoạt động ngày hôm nay. Xin chân thành thứ lỗi."
L11_1.m_Talk_VTN = L12_1
L12_1 = "刚才有一艘次元舰船撞到了我们酒店楼顶，所以暂时没办法接待您了。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Da ein Dimensionsschiff auf unserem Dach abgestürzt ist, ist das Hotel heute nicht im Betrieb. Das tut uns sehr leid."
L11_1.m_Talk_DEU = L12_1
L12_1 = "J'ai le regret de vous informer que suite au crash d'un vaisseau dimensionnel sur le toit de l'hôtel, nous ne serons pas en service aujourd'hui. Veuillez nous excuser."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SUMMER2021_ACT1_PROLOGUE@112#Talk"
