L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L12_1.m_Crash = 30
L13_1 = "뭐시라?! 함선이 들이받아?!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "なんだと！？　艦船が衝突！？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "What?! A dimensional ship crashed your building?!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "什麼？被艦船撞到？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ว่าไงนะครับ?! ยานข้ามมิติชนอาคารของคุณเหรอ?!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Cái gì? Một chiến hạm đa chiều đã va chạm vào sân thượng của tòa nhà?!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "你说什么？！次元舰船？！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Was?! Ein Dimensionsschiff ist auf Ihr Gebäude gestürzt?!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Quoi ?! Un vaisseau dimensionnel s'est écrasé sur votre bâtiment ?!"
L12_1.m_Talk_FRA = L13_1
