L15_1 = "SUMMER2021_ACT1_PROLOGUE@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3200101
L14_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "STAFF_NPC_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "네. 사고 경위를 파악 중인 조사관에 따르면 일사병으로 인한 오퍼레이터의 조종 실수가 유력하다고 합니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "はい。事故の経緯を把握している調査官によると、熱中症によるオペレーターの操縦ミスが原因だそうです。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Yes. The investigator says it’s highly likely that the operator suffered heat stroke and lost control..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "是的。正在調查意外經過的調查人員表示，很可能是因為領航員中暑，導致操作失誤。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ใช่ค่ะ เจ้าหน้าที่สืบสวนบอกว่าเป็นไปได้่ว่าเกิดจากการที่คนขับยานเป็นลมแดดแล้วก็หมดสติ..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Đúng vậy. Điều tra viên cho biết rất có thể người vận hành đã bị say nhiệt và mất kiểm soát..."
L14_1.m_Talk_VTN = L15_1
L15_1 = "是的。据正在调查事故原因的调查官说，很有可能是中暑导致机务员操作失误造成的。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ja. Der Ermittler sagt, es sei sehr wahrscheinlich, dass der Bediener einen Hitzschlag erlitt und die Kontrolle verlor ..."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Oui. D'après les résultats de l'enquête, il semblerait que l'opérateur ait perdu le contrôle suite à un coup de chaleur."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
