L21_1 = "혹시 이거 몰래 카메라입니까? 마지막엔 스승님이 미안하다면서 도망치고 끝나나요?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "もしかしてドッキリですか？　最後は師匠がすまないと言って、逃げるのがオチですかね？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Boss, is this a candid camera? Does this show end with the Master running away saying she’s sorry?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "這是惡作劇嗎？等一下師父該不會突然出現，然後說句對不起就跑掉？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "บอสคะ นี่รายการตั้งกล้องแอบถ่ายเหรอคะ? ปกติรายการแบบนี้พิธีกรต้องวิ่งหนีแล้วบอกว่าขอโทษใช่มั้ย?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Đây là camera ẩn à? Show này kết thúc với việc Hilde bỏ chạy rồi nói xin lỗi à?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "哈啊，总感觉有些潦草的样子。你不会是要像当时的老师一样说声对不起，然后就偷偷跑开了吧？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Boss, ist das eine versteckte Kamera? Endet diese Show damit, dass meine Meisterin wegrennt und sagt, dass es ihr leid tut?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "C'est quoi, une caméra cachée ? À la fin, le Maître prend la fuite en s'excusant pour tout ce qu'elle a fait, peut-être ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
