L22_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "R"
L21_1.m_Crash = 30
L22_1 = "크흠, 흠! 사고야 언제 어디서든 일어날 수 있지!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "こ、こほん！　事故はいつどこにでもあり得ることだ！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Ahem! Hmm! Accidents can happen!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "咳咳，嗯！意外本來就是無法預期的嘛！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อะแฮ่ม! เอ่ออ! อุบัติเหตุมันเกิดขึ้นได้น่ะ!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ahem! Hmm! Tai nạn có thể xảy ra mà!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "咳咳，咳！事故随时随地都有可能发生！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Hm! Hmm! Unfälle können passieren!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Ahem, hem ! Les accidents ça arrive, non ?"
L21_1.m_Talk_FRA = L22_1
