L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3200101
L23_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_PRIDE"
L24_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "하지만 걱정 말게. 내가 누군가."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "しかし心配するな。私が誰なのか知っているだろ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "But don’t worry. You know me."
L23_1.m_Talk_ENG = L24_1
L24_1 = "不過你不要擔心！就相信我吧！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แต่ไม่ต้องห่วงครับ คุณก็รู้จักผมนี่"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nhưng đừng lo. Cô biết tôi mà."
L23_1.m_Talk_VTN = L24_1
L24_1 = "不过别担心，你以为我是谁！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Aber keine Sorge. Sie kennen mich doch."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Mais ne t'inquiète pas. Tu me connais !"
L23_1.m_Talk_FRA = L24_1
