L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3200101
L24_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_LAUGH"
L25_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L24_1.m_Crash = 30
L25_1 = "이런 일이 있을 줄 알고 자네의 휴가 계획을 플랜 A부터 AXZ까지 마련해 뒀다네!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "こんなこともあろうかと思って、君の夏休み計画はプランAからAXZまで用意しているのさ！"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I knew something like this was going to happen, so I planned everything from A to AXZ!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "我早就知道會發生這樣的事，你的假期安排，我從A計畫到Z計畫都已經準備妥當！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ผมรู้ว่าเรื่องแบบนี้เกิดขึ้นได้ ผมเลยวางแผนทุกอย่างไว้ตั้งแต่ต้นจนจบแล้ว!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi biết chuyện như thế này sẽ xảy ra, vì vậy tôi đã lên kế hoạch cho mọi thứ từ A đến AXZ!"
L24_1.m_Talk_VTN = L25_1
L25_1 = "我就知道会发生这种事，所以给你准备了A计划到AXZ计划等一系列休假计划！"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich wusste, dass so etwas passieren würde, also habe ich alles von A bis AXZ geplant!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Je me doutais que quelque chose comme ça allait arriver, alors j'ai tout planifié de A à AXZ !"
L24_1.m_Talk_FRA = L25_1
