L27_1.m_Face = "UNIT_SURPRISE"
L28_1 = "NAHEERIN_COFFIN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L27_1.m_Crash = 20
L28_1 = "네?! 사장님, 코핀 함은 전사 휴무라 정기 수리 보내 뒀는데요?!"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "え！？　社長、コフィン艦は全社休業で定期修理に出していますよ！？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Huh?! But Boss, Coffin was sent for repair as today is a day-off!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "嗯？！老闆，科芬公司因為全公司放假，就把科芬艦送到這來定期維護咧？！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "หืม?! บอสคะ คอฟฟินถูกส่งไปซ่อมเพราะวันนี้เป็นวันหยุดนี่คะ!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Hử?! Nhưng Sếp, Coffin đã được điều đến để sửa chữa vì hôm nay là ngày nghỉ!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "嗯？！老板，因为全公司都放假，科芬舰也送去定期维修了。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Wie bitte?! Aber Boss, das Coffin-Schiff wurde zur Reparatur geschickt, da heute Betriebsurlaub ist!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Hein ?! Mais Monsieur, le Coffin a été envoyé en réparation aujourd'hui !"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
