L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3200101
L28_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
