L29_1 = "UNIT_TOUCH"
L28_1.m_Face = L29_1
L29_1 = "NAHEERIN_COFFIN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "m_bFaceLoop"
L28_1[L29_1] = false
L29_1 = 40
L28_1.m_Crash = L29_1
L29_1 = "아?! 스톱! 거기 아저씨 스톱! 제 선풍기라고요, 그거!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "あっ！？　ストップストップ！　それは私の扇風機なのです！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Oh?! Stop, hey, stop! That’s my fan!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "哦？！停！那邊的叔叔停下！那是我的電風扇啦！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "อ้าว?! หยุดนะ นี่ หยุดนะ! นั่นพัดลมของฉันนะคะ!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ồ?! Dừng lại, này, dừng lại! Đó là quạt của tôi!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "啊？！站住！那个大叔你站住！那个，是我的风扇！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Oh?! Stopp, hey, stopp! Das ist mein Ventilator!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ah ?! Stop ! Mais arrêtez, enfin ! C'est mon ventilateur, ça !"
L28_1.m_Talk_FRA = L29_1
