L29_1.m_Face = "UNIT_IDLE"
L30_1 = "NAHEERIN_COFFIN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L29_1.m_Crash = 30
L30_1 = "사장님, 격납고에 에어컨 좀 더 달아 주시면 안 될까요? 정비원 분들이 자꾸 떼어 가서요!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "社長、格納庫にエアコンを増やしてくれませんか？　整備士たちが勝手に持っていっちゃうのです。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Boss, could you get us more air-conditioners in the Hangar? The mechanics are constantly taking away the air-cons!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "老闆，能不能在機庫裡再多裝幾台冷氣？維修人員老是把冷氣拆走！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "บอสคะ คุณช่วยติดแอร์เพิ่มในโรงจอดยานได้มั้ยคะ? เครื่องจักรกลมันดูดแอร์ไปตลอดเลย!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Sếp, chúng ta có thể lắp thêm điều hòa trong Hangar không? Các thợ cơ khí cứ lấy điều hoà đi thôi!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "老板，在机库里多装一些空调不行吗？经常被维修技师们拆走！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Boss, könnten wir mehr Klimaanlagen im Hangar haben? Die Mechaniker nehmen sie uns ständig weg!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Dites, Monsieur le Directeur... On pourrait avoir plus de climatiseurs au Hangar ? Les mécaniciens n'arrêtent pas de venir nous piller !"
L29_1.m_Talk_FRA = L30_1
