L33_1 = "SUMMER2021_ACT1_PROLOGUE@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3200101
L32_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_DESPAIR"
L33_1 = "KIMHANA_COFFIN_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "네. 그라운드 원을 떠나는 항공편은 현재 급성 침식 현상 때문에 전부 결항 상태입니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "はい。グラウンド・ワンを発つ航空便は、現在急性侵食現象により全て欠航状態です。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Yes, all flights heading out from Ground One are suspended due to the acute Counterside Effect."
L32_1.m_Talk_ENG = L33_1
L33_1 = "是的。離開 G1 的航班，目前因緊急侵蝕現象全部停飛。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ใช่ ทุกเที่ยวบินที่มุ่งหน้าออกจากกราวด์วันถูกระงับเนื่องจากปรากฏการณ์เคาน์เตอร์ไซด์เฉียบพลัน"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đúng thế, tất cả các chuyến bay từ Ground One đều bị tạm dừng do Hiệu Ứng Ăn Mòn nghiêm trọng."
L32_1.m_Talk_VTN = L33_1
L33_1 = "是。受急性侵蚀现象影响，离开G1的航班现在全都处于停飞状态。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ja, alle Flüge, die von Ground One abfliegen, werden aufgrund des akuten Verderbnissyndroms ausgesetzt."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Oui, tous les vols au départ du Site n°1 sont suspendus en raison d'Effets du Contremonde particulièrement violents."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SUMMER2021_ACT1_PROLOGUE@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3200101
L33_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "KIMHANA_COFFIN_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "여객선들도 이상기후로 발생한 태풍 탓에 오늘 내로 출항하긴 어렵다고 하네요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "旅客船も異常気象で発生した台風のせいで、今日中に出航するのは難しいそうです。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Also, passenger ships won’t be leaving the city today because of the storm."
L33_1.m_Talk_ENG = L34_1
L34_1 = "據說客輪也因氣候異常而發生的颱風，今天看來是很難出航。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "และยานโดยสารก็ออกจากเมืองในวันนี้ไม่ได้เพราะมีพายุ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Đồng thời, các thuyền chở khách cũng sẽ không rời khỏi thành phố trong hôm nay do cơn bão."
L33_1.m_Talk_VTN = L34_1
L34_1 = "客轮方面也表示，受异常气候引发的台风影响，今天无法出港。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Auch Fahrgastschiffe verlassen die Stadt heute wegen des Sturms nicht."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Par ailleurs, un typhon empêche actuellement tous les vaisseaux de croisière de quitter la ville."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "SUMMER2021_ACT1_PROLOGUE@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3200101
L34_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_LAUGH"
L35_1 = "KIMHANA_COFFIN_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "그리고 비상 대기 중인 힐데 소대장님이 사장님께 긴히 할 얘기가 있으시다고───"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "そして非常待機中のヒルデ小隊長が社長に大事なことがあると───"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Commander Hilde is on emergency stand-by, and wants to talk to you—"
L34_1.m_Talk_ENG = L35_1
L35_1 = "另外，緊急待命中的希爾德隊長說有急事找老闆───"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ผู้บัญชาการฮิลเด้กำลังสแตนด์บายเผื่อสถานการณ์ฉุกเฉิน และฉันก็อยากคุยกับคุณ..."
L34_1.m_Talk_THA = L35_1
L35_1 = "Tổng Tư Lệnh Hilde đang ở tuyến chờ khẩn cấp và muốn nói chuyện với ngài—"
L34_1.m_Talk_VTN = L35_1
L35_1 = "还有，紧急待命中的希尔德小队长说有要紧事要跟老板您说——"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Kommandantin Hilde ist in Notbereitschaft und möchte mit Ihnen sprechen ..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "La commandante Hilde est en stand-by pour une entrevue d'urgence."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
