L38_1 = "SUMMER2021_ACT1_PROLOGUE@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3200101
L37_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_DESPAIR"
L38_1 = "LEEYOONJUNG_COFFIN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L37_1.m_Crash = 20
L38_1 = "네에…… 모의전 시뮬레이션은 지금 긴급 점검 중입니다……"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "はあ……模擬戦シミュレーションはただいま緊急メンテナンスなんです……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Yes... Simulation is currently under emergency maintenance..."
L37_1.m_Talk_ENG = L38_1
L38_1 = "是. 模擬戰模擬器目前緊急維護中…"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ใช่ค่ะ... ปฏิบัติการจำลองก็กำลังอยู่ระหว่างการซ่อมบำรุงฉุกเฉิน..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Đúng vậy... Mô Phỏng Tác Chiến hiện đang được bảo trì khẩn cấp..."
L37_1.m_Talk_VTN = L38_1
L38_1 = "是……模拟战模拟器现在正在紧急检修……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ja ... Die Simulation wird derzeit eilig gewartet ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Oui... La simulation est en cours de maintenance exceptionnelle..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "SUMMER2021_ACT1_PROLOGUE@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3200101
L38_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "LEEYOONJUNG_COFFIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L38_1.m_Crash = 15
L39_1 = "직원 분들이 요즘 자주 사용하셔서요, 네…… 휴양지는 구현하기 어렵다네요……"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "社員の方が最近よく使っているので、はい……リゾート地は再現するのが難しいようです……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "The employees have been using it often lately... Yes, it’s hard to render a resort..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "因為最近員工使用太頻繁，是…度假村可能做不出來… "
L38_1.m_Talk_TWN = L39_1
L39_1 = "พักหลังนี้พนักงานใช้งานกันบ่อย... ใช่ค่ะ ไม่มีทางเลือกอื่นเลย..."
L38_1.m_Talk_THA = L39_1
L39_1 = "Các nhân viên gần đây đã sử dụng nó thường xuyên... Đúng vậy, thật khó để có một giải pháp..."
L38_1.m_Talk_VTN = L39_1
L39_1 = "因为职员们最近经常使用……所以要临时模拟出度假地有些困难……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Die Mitarbeiter haben es in letzter Zeit oft benutzt ... Ja, es ist schwer, ein Resort zu rendern ..."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Elle a été beaucoup utilisée ces derniers temps, oui... Une station balnéaire, c'est pas facile à reproduire...."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "SUMMER2021_ACT1_PROLOGUE@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3200101
L39_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_SURPRISE"
L40_1 = "LEEYOONJUNG_COFFIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "……오늘부터 전사 휴무요? 새로 나온 논문 이름인가요?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "……今日から全社休業ですか？　それって新しい論文の名前ですか？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "... Company day-off? Is that a new thesis title?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "…全公司從今天開始放假？這是新出刊的論文題目嗎？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "...วันหยุดบริษัทเหรอ? ชื่อหัวข้อวิทยานิพนธ์ใหม่รึไง?"
L39_1.m_Talk_THA = L40_1
L40_1 = "... Ngày nghỉ của công ty? Đó là một tiêu đề luận văn mới à?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "……从今天开始全公司放假？这是新出来的研究论文课题吗？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ein Betriebsurlaub, ab heute? Ist das ein neuer Diplomarbeitstitel?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "... Un congé d'entreprise ? C'est le titre d'un nouvel article de recherche ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
