L44_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "L"
L44_1 = "플랜 A부터 AXZ까지 전부 실패로군요. 훌륭합니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "プランAからAXZまで全部失敗ですね。お見事です。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "So, everything from A to AXZ is a failure. Great."
L43_1.m_Talk_ENG = L44_1
L44_1 = "計畫A到Z計畫全部失敗了，真是好棒棒！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แปลว่าทุกอย่างพังทั้งหมดเลยสิ เยี่ยม"
L43_1.m_Talk_THA = L44_1
L44_1 = "Thế nên, mọi thứ từ A đến AXZ là một thất bại. Tuyệt vời."
L43_1.m_Talk_VTN = L44_1
L44_1 = "从A计划到AXZ计划全都失败了呢。您可真行啊。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Also ist alles von A bis AXZ ein Misserfolg. Großartig."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Tous les plans ont échoué, de A à AXZ. Prodigieux."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "SUMMER2021_ACT1_PROLOGUE@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3200101
L44_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_SURPRISE"
L45_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "R"
L45_1 = "말도 안 돼! 설마 마왕 중의 누군가가 꾸민 계략인가!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ありえない！　まさか魔王の誰かが企んだ計略か？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "This can’t be! Maybe it’s a Demon Lord’s doing!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "太誇張了吧！是哪個魔王在弄我嗎？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เป็นไปไม่ได้! หรือจะเป็นฝีมือเจ้าแห่งดีม่อน!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Không thể thế được! Có lẽ đây là hành động của Chúa Quỷ!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "不可能！难道是某个魔王使的手段！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Das kann nicht sein! Vielleicht ist es das Werk eines Dämonenfürsten!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Impossible ! C'est sûrement l'œuvre d'un seigneur démon !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "SUMMER2021_ACT1_PROLOGUE@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3200101
L45_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "R"
L45_1.m_Crash = 30
L46_1 = "기껏 수영복까지 사 왔는데 이럴 수는 없어!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "せっかく水着まで買ってきたのに！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I even brought you a swimsuit!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "我還特地買了泳衣，我不會放棄的！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ผมเอาชุดว่ายน้ำมาให้คุณด้วยนะ!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi thậm chí còn mua cho cô một bộ đồ bơi!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "我好不容易买来了泳装，这样可不行！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich habe Ihnen sogar einen Bikini mitgebracht!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je t'avais même apporté un maillot de bain... !"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "SUMMER2021_ACT1_PROLOGUE@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3200101
L46_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_DESPAIR"
L47_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "L"
L47_1 = "대로에서 큰소리로 말씀하지 마시죠. 부끄러우니까요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "道端で大声で叫ぶのはおやめください。こっちが恥ずかしいです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Stop yelling in the middle of the street. You’re embarrassing me."
L46_1.m_Talk_ENG = L47_1
L47_1 = "大庭廣眾之下不要大聲嚷嚷，很丟人。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เลิกตะโกนกลางถนนได้แล้วค่ะ คุณทำฉันอายนะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đừng có la hét giữa đường nữa. Anh đang làm tôi mất mặt đấy."
L46_1.m_Talk_VTN = L47_1
L47_1 = "您还是不要在街上大声嚷嚷了，太丢人了。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hören Sie auf, mitten auf der Straße zu schreien. Sie blamieren mich."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Arrêtez de crier comme ça au milieu de la rue. Vous m'embarrassez."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
