L49_1 = "SUMMER2021_ACT1_PROLOGUE@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3200101
L48_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_IDLE"
L49_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "아무튼, 전 결국 집에서 휴가를 보내야 할 운명 같군요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "私は結局、家で休む運命だったようですね。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Anyway, I guess I’m destined to spend the day-off at home."
L48_1.m_Talk_ENG = L49_1
L49_1 = "總之，我命中註定要在家度假。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "สงสัยฟ้าคงลิขิตให้ฉันใช้เวลาวันหยุดอยู่บ้าน"
L48_1.m_Talk_THA = L49_1
L49_1 = "Dù sao thì, tôi đoán số của mình là phải dành ngày nghỉ ở nhà rồi."
L48_1.m_Talk_VTN = L49_1
L49_1 = "总之，我似乎又变成在家度过假期的命运了呢。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wie auch immer, ich denke, ich bin dazu verdammt, den Urlaub zu Hause zu verbringen."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Quoi qu'il en soit, je suppose que je vais devoir passer ma journée de repos à la maison."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "SUMMER2021_ACT1_PROLOGUE@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3200101
L49_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "사장님도 이 더위에 돌아다니지 마시고 얌전히 집에서 쉬시죠."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "社長もこの暑さで外にいるのは危ないですし、大人しく自宅で休んでください。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Boss, you should go home too. It’s too hot to stay outside."
L49_1.m_Talk_ENG = L50_1
L50_1 = "天氣這麼熱，老闆也別亂跑，乖乖待在家休息吧。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "บอสคะ คุณก็ควรจะกลับบ้านเหมือนกันนะ วันนี้ร้อนเกินกว่าจะอยู่นอกบ้านนะคะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Sếp, anh cũng nên về nhà đi. Trời quá nóng không ở ngoài được đâu."
L49_1.m_Talk_VTN = L50_1
L50_1 = "这大热天的，老板您也别到处转悠了，就老老实实地在家休息吧。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Boss, Sie sollten auch nach Hause gehen. Es ist zu heiß, um draußen zu bleiben."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Vous aussi, vous devriez rentrer. Il fait trop chaud pour rester dehors."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
