L2_1 = "SUMMER2021_ACT1_PROLOGUE@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3200101
L1_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "CUTSCENE_AMBIENT_WIND"
L1_1.m_StartBGMFileName = L2_1
L2_1 = "FX_CUTSCEN_SIREN"
L1_1.m_StartFXSoundName = L2_1
L2_1 = "<color=#ffd34c>도시관리국에서 안내드립니다. 현재 이 방송이 들리는 주거 구역은 대규모 정전 사태가 발생한 상황입니다.</color>"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "<color=#ffd34c>都市管理局からご案内します。現在、この放送が流れる住居区域に大規模停電が発生しています。</color>"
L1_1.m_Talk_JPN = L2_1
L2_1 = "<color=#ffd34c>This is an announcement from City Management. If you’re hearing this, it means you’re in a residential zone with a large-scale blackout.</color>"
L1_1.m_Talk_ENG = L2_1
L2_1 = "<color=#ffd34c>城市管理局通知，現在收聽得到這個廣播的地區發生大規模停電。</color>"
L1_1.m_Talk_TWN = L2_1
L2_1 = "<color=#ffd34c>ประกาศจากสำนักบริหารเมือง หากคุณได้ยินประกาศนี้ นั่นหมายความว่าคุณอยู่ในเขตที่พักอาศัยที่เกิดไฟดับเป็นวงกว้าง</color>"
L1_1.m_Talk_THA = L2_1
L2_1 = "<color=#ffd34c>Đây là một thông báo từ Ban Quản Lý Thành Phố. Nếu bạn đang nghe thông báo này, có nghĩa là bạn đang ở trong khu dân cư bị mất điện diện rộng.</color>"
L1_1.m_Talk_VTN = L2_1
L2_1 = "<color=#ffd34c>城市管理局播报通知，当前收到播报的居住区内发生了大规模停电事故。</color>"
L1_1.m_Talk_SCN = L2_1
L2_1 = "<color=#ffd34c>Dies ist eine Ankündigung der Stadtverwaltung. Wenn Sie dies hören, befinden Sie sich in einem Wohngebiet mit einem großflächigen Stromausfall.</color>"
L1_1.m_Talk_DEU = L2_1
L2_1 = "<color=#ffd34c>Ceci est une annonce de la Direction des cités. Si vous nous entendez, cela signifie que vous êtes dans une zone résidentielle faisant l'objet d'une panne d'électricité à grande échelle.</color>"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "SUMMER2021_ACT1_PROLOGUE@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3200101
L2_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "<color=#ffd34c>시민 여러분은 전력 공급이 복구되기 전까지 그늘진 곳에서 기다려 주시고…….</color>"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "<color=#ffd34c>市民の皆さんは電力供給が復旧されるまで、日陰でお待ちいただくよう……</color>"
L2_1.m_Talk_JPN = L3_1
L3_1 = "<color=#ffd34c>Please hold on until the power is restored. Stay in the shade...</color>"
L2_1.m_Talk_ENG = L3_1
L3_1 = "<color=#ffd34c>請市民們在恢復供電之前，在陰涼處等待………</color>"
L2_1.m_Talk_TWN = L3_1
L3_1 = "<color=#ffd34c>โปรดรอจนกว่าเราจะกู้ไฟฟ้าได้และอยู่ในที่ร่มเข้าไว้...</color>"
L2_1.m_Talk_THA = L3_1
L3_1 = "<color=#ffd34c>Vui lòng cầm cự cho đến khi nguồn điện được khôi phục. Hãy ở trong bóng râm...</color>"
L2_1.m_Talk_VTN = L3_1
L3_1 = "<color=#ffd34c>望广大市民在恢复供电之前在阴凉处等待……</color>"
L2_1.m_Talk_SCN = L3_1
L3_1 = "<color=#ffd34c>Bitte warten Sie, bis die Stromversorgung wiederhergestellt ist. Bleiben Sie im Schatten und ...</color>"
L2_1.m_Talk_DEU = L3_1
L3_1 = "<color=#ffd34c>Veuillez patienter jusqu'à ce que le courant soit rétabli. Et restez à l'ombre...</color>"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "SUMMER2021_ACT1_PROLOGUE@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3200101
L3_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_LAUGH"
L4_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "귀가하기 전에 발전소 담당자를 추궁하러 가야겠군요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "帰宅する前に発電所の担当者を追及しに行かなければなりませんね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I think I’ll go and question the plant operator before I go home."
L3_1.m_Talk_ENG = L4_1
L4_1 = "看來回家前必須先去向發電廠的負責人究責。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันว่าฉันจะไปถามคำถามผู้ดูแลโรงไฟฟ้าก่อนกลับบ้าน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tôi nghĩ tôi sẽ đi hỏi người điều hành nhà máy điện trước khi về nhà."
L3_1.m_Talk_VTN = L4_1
L4_1 = "看来回家之前先得好好拜访一下发电站的负责人。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ich glaube, ich gehe und verhöre den Anlagenbetreiber, bevor ich nach Hause gehe."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je pense que je vais aller interroger l'opérateur de la centrale avant de rentrer."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "SUMMER2021_ACT1_PROLOGUE@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3200101
L4_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "회사에서 제 장비를 가져 와야겠습니다. 비상 사태니 상관없겠죠?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "会社から私の装備を持って来ます。非常事態ですから問題ないでしょう？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "First, I need my gear from the company. It’s an emergency, so it’s okay, right?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "我要去公司拿我的裝備，現在是緊急狀況，應該沒關係吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ก่อนอื่นฉันต้องไปเอาอุปกรณ์จากบริษัท นี่เป็นเรื่องฉุกเฉิน ดังนั้นคงไม่มีปัญหาใช่มั้ยคะ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Trước hết, tôi cần trang bị của mình từ công ty. Đây là một trường hợp khẩn cấp, nên không sao, đúng không?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "我得去公司把我的装备拿来。事态紧急，所以应该没关系吧？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Zuerst brauche ich meine Ausrüstung von der Firma. Es ist ein Notfall, also ist es okay, oder?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais avant, je vais avoir besoin de mon équipement. C'est une urgence, alors il ne devrait pas y avoir de problème ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
