L8_1 = "SUMMER2021_ACT1_PROLOGUE@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3200101
L7_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_SURPRISE"
L8_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "R_M_I"
L8_1 = "기다리게, 부사장! 도시관리국이랑 싸워서 어쩌려고!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "待ってくれ、副社長！　都市管理局と戦ってどうするんだ！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Halt, Vice President! Why would you fight the City Management?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "副總請留步！和城市管理局吵架有什麼用！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "หยุดเลยครับ คุณรองประธาน! คุณจะไปสู้กับสำนักบริหารเมืองทำไมกัน?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Dừng lại, Phó Chủ Tịch! Sao cô lại định đánh Ban Quản Lý Thành Phố chứ?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "喂喂！等一下！我怎么感觉你要跟城市管理局打起来的样子！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Halt, Vizepräsidentin! Warum würden Sie gegen die Stadtverwaltung kämpfen?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Halte, vice-présidente ! Combattre la Direction des cités ? Mais à quoi est-ce que tu penses ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "SUMMER2021_ACT1_PROLOGUE@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3200101
L8_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_DESPAIR"
L9_1 = "FX_CUTSCEN_NOISE_RUSTLE"
L8_1.m_StartFXSoundName = L9_1
L9_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "R"
L8_1.m_Crash = 20
L9_1 = "자, 마지막 비장의 수단이 남아 있어. 이 방법이라면 확실할 걸세."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "まあ、最後の切り札が残っている。この方法なら間違いないだろう。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Look, I still have a card up my sleeve. I’m sure it will work."
L8_1.m_Talk_ENG = L9_1
L9_1 = "好吧！我還有最後的必殺技，這個方法肯定OK！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ฟังนะ ผมมีทางเลือกสุดท้าย ผมมั่นใจว่าจะได้ผล"
L8_1.m_Talk_THA = L9_1
L9_1 = "Nghe này, tôi có một giải pháp cuối cùng. Tôi chắc là nó sẽ thành công."
L8_1.m_Talk_VTN = L9_1
L9_1 = "好了，还剩下最后一个杀手锏。用这个办法一定能搞定。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Schauen Sie, das ist mein letzter Ausweg. Ich bin sicher, es wird funktionieren."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Attends, j'ai une idée. Un dernier recours. Je suis sûr que ça marchera."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "SUMMER2021_ACT1_PROLOGUE@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3200101
L9_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_SURPRISE"
L10_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "L"
L10_1 = "이건…… 플로라 메이드 서비스의 전단지 아닙니까?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "これは……フローラメイドサービスのチラシ？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "This is... Flora Maid Service's ad flyer."
L9_1.m_Talk_ENG = L10_1
L10_1 = "這…是芙蘿拉女僕服務公司的傳單吧？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "นี่มัน... ใบปลิวโฆษณาบริการเมดฟลอร่านี่"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đây là... là tờ rơi quảng cáo của Dịch Vụ Người Hầu Hoa."
L9_1.m_Talk_VTN = L10_1
L10_1 = "这个……不是弗罗拉女仆服务的传单吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Das ist ... ein Werbeflyer vom Hausmädchenservice Flora."
L9_1.m_Talk_DEU = L10_1
L10_1 = "C'est... un dépliant publicitaire du Service domestique Flora ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "SUMMER2021_ACT1_PROLOGUE@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3200101
L10_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "R"
L11_1 = "역시 자네야. 이 초현실주의 미술 작품을 단번에 알아보는군."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "さすが君だ。この超現実主義の美術品にすぐ気付くとは。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I knew it. I knew you would recognize this surrealist artwork."
L10_1.m_Talk_ENG = L11_1
L11_1 = "不愧是副總！一眼就認出這幅超現實主義的美術作品！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "กะแล้วว่าคุณต้องจำได้จากงานศิลปะเหนือจริงนี้"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi biết ngay mà. Tôi biết là cô sẽ nhận ra tác phẩm nghệ thuật siêu thực này."
L10_1.m_Talk_VTN = L11_1
L11_1 = "你果然厉害。一下子就认出这么超现实主义的美术作品了呢。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich wusste es. Ich wusste, dass Sie dieses surrealistische Kunstwerk erkennen würden."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je le savais. Je savais que vous reconnaîtriez cette œuvre surréaliste."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
