L13_1 = "SUMMER2021_ACT1_PROLOGUE@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3200101
L12_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_IDLE"
L13_1 = "THEMA_CHILD"
L12_1.m_StartBGMFileName = L13_1
L13_1 = "FX_CUTSCEN_PHONE"
L12_1.m_StartFXSoundName = L13_1
L13_1 = "LEADER_MAID_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "m_bCharHologramEffect"
L12_1[L13_1] = true
L13_1 = "연락해 주시기를 기다리고 있었습니다. 주인님."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ご連絡をお待ちしておりました、ご主人様。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I was waiting for your call, Master."
L12_1.m_Talk_ENG = L13_1
L13_1 = "我一直在等候您來電呢，主人。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "กำลังรอให้คุณโทรมาอยู่เลยค่ะ นายท่าน"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi đang chờ ngài gọi đây, Chủ Nhân."
L12_1.m_Talk_VTN = L13_1
L13_1 = "我一直在等您联系我，尊敬的主人。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich habe auf Ihren Anruf gewartet, Meister."
L12_1.m_Talk_DEU = L13_1
L13_1 = "J'attendais votre appel, Maître."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SUMMER2021_ACT1_PROLOGUE@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3200101
L13_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_PRIDE"
L14_1 = "LEADER_MAID_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "메이드장 베로니카, 인사드립니다. 그간 무탈하게 지내셨는지요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "メイド長ベロニカ、ご挨拶申し上げます。お変わりございませんか。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Chief Maid Veronica, at your service. I hope you fared well."
L13_1.m_Talk_ENG = L14_1
L14_1 = "女僕長 貝洛妮卡向您問安，別來無恙。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "หัวหน้าเมดเวโรนิกาพร้อมให้บริการค่ะ หวังว่าคุณจะสบายดีนะคะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Trưởng Hầu Gái Veronica, sẵn sàng phục vụ. Tôi hy vọng là ngài vẫn ổn."
L13_1.m_Talk_VTN = L14_1
L14_1 = "我是女仆长贝罗尼卡，在此向您致敬。这段时间您过得好吗？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Oberstes Hausmädchen Veronica, zu Ihren Diensten. Ich hoffe, es ist Ihnen gut ergangen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Gouvernante Veronica, à votre service. Comment vous portez-vous ?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
