L17_1 = "SUMMER2021_ACT1_PROLOGUE@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3200101
L16_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_LAUGH"
L17_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "R"
L17_1 = "오오. 오랜만일세, 베로니카 양."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ああ、久々だな。ベロニカ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Oh, it’s been a while, Veronica."
L16_1.m_Talk_ENG = L17_1
L17_1 = "喔喔～好久不見了，貝洛妮卡。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ไม่ได้พบกันนานเลยนะ เวโรนิกา"
L16_1.m_Talk_THA = L17_1
L17_1 = "Ồ, đã lâu rồi nhỉ, Veronica."
L16_1.m_Talk_VTN = L17_1
L17_1 = "噢噢，好久没联系了，贝罗尼卡。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Oh, es ist eine Weile her, Veronica."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Oh, ça fait un bail, Veronica !"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "SUMMER2021_ACT1_PROLOGUE@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3200101
L17_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_DESPAIR"
L18_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "R"
L18_1 = "우린 지금 중대한 난관에 봉착했다네. 자네 힘이 필요한 순간이야."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "我々は今重大な困難に直面している。君の力が必要な時が来た。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "We’re currently in big trouble. We really need your help."
L17_1.m_Talk_ENG = L18_1
L18_1 = "我們現在面臨到重大難題，正是需要你的時候！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ตอนนี้เราเจอปัญหาใหญ่ เราต้องการให้คุณช่วย"
L17_1.m_Talk_THA = L18_1
L18_1 = "Chúng tôi đang gặp phải một rắc rối lớn. Chúng tôi thực sự cần cô giúp."
L17_1.m_Talk_VTN = L18_1
L18_1 = "我们现在遇上大难题了，需要你的帮助。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wir sind derzeit in großen Schwierigkeiten. Wir brauchen Ihre Hilfe."
L17_1.m_Talk_DEU = L18_1
L18_1 = "En fait, j'ai un petit problème et j'ai besoin de ton aide."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "SUMMER2021_ACT1_PROLOGUE@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3200101
L18_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "LEADER_MAID_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "L"
L19_1 = "주인님께서 원하신다면 얼마든지 도와드리겠습니다. 어떤 고민이신지요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ご主人様のお望みならば、何なりとお申し付けください。どのようなお悩みでしょうか。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "As you wish, Master. What is it that you want?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "只要主人一句話，我都會盡我所能地協助，請問是什麼難題呢？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ได้เลยค่ะ นายท่าน คุณต้องการอะไรเหรอคะ?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Theo ý ngài, thưa Chủ Nhân. Ngài cần gì thế ạ?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "只要主人需要，我随时都愿意帮忙。请问您遇到什么麻烦了？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Wie Sie wünschen, Meister. Was wünschen Sie?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Tout ce que vous voulez, Maître. Comment puis-je vous être utile ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
