L22_1 = "SUMMER2021_ACT1_PROLOGUE@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3200101
L21_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "LEADER_MAID_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "m_bCharHologramEffect"
L21_1[L22_1] = true
L22_1 = "요약하면 부사장님께서 만족하실 만한 휴양지로 찾고 계신다는 말씀이시군요."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "要するに、副社長が満足できそうなリゾート地をお探しということですね。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "So to summarize, you’re looking for a good vacation spot for the Vice President."
L21_1.m_Talk_ENG = L22_1
L22_1 = "簡單來說，就是您正在尋找副總會滿意的度假村對吧？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "สรุปก็คือคุณกำลังมองหาที่พักผ่อนดีๆ สำหรับรองประธาน"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tóm lại là ngài đang tìm một điểm nghỉ mát cho Phó Chủ Tịch."
L21_1.m_Talk_VTN = L22_1
L22_1 = "简而言之，您现在正在寻找能让副总满意的度假地点。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Zusammenfassend suchen Sie also nach einem guten Urlaubsort für die Vizepräsidentin."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Donc pour résumer, vous cherchez une destination de vacances qui convienne à la vice-présidente."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "SUMMER2021_ACT1_PROLOGUE@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3200101
L22_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "미안하네. 지구 반대편에 있는 자네한테 어려운 부탁인 줄은 아네만……."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "すまない。今地球の反対側にいる君に難しい依頼であるのは承知の上だが……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I’m sorry. I know it’s a difficult task, considering that you’re on the other side of the Earth and all..."
L22_1.m_Talk_ENG = L23_1
L23_1 = "很抱歉，我知道這個請求，對於身處地球另一端的你來說有點為難……"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ขอโทษทีนะ ผมรู้ว่ามันเป็นงานที่ยาก เพราะคุณก็อยู่อีกฟากหนึ่งของโลก..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi xin lỗi. Tôi biết đây là một nhiệm vụ khó, khi nghĩ tới cô đang ở phía bên kia Trái Đất..."
L22_1.m_Talk_VTN = L23_1
L23_1 = "对不起。我也知道这个要求有点过分了，你现在还在地球的另一边吧……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Es tut mir leid. Ich weiß, dass es eine schwierige Aufgabe ist, wenn man bedenkt, dass Sie sich auf der anderen Seite der Erde befinden ..."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Désolé de te demander ça. Je suis sûr que ça ne doit pas être facile, vu que tu es de l'autre côté de la terre..."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "SUMMER2021_ACT1_PROLOGUE@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3200101
L23_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_PRIDE"
L24_1 = "LEADER_MAID_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "m_bCharHologramEffect"
L23_1[L24_1] = true
L24_1 = "그 말씀은 부디 거두어 주시길. 주인님께 보탬이 되는 것은 메이드의 보람입니다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "滅相もないことでございます。ご主人様のお役に立つことこそ、メイドの喜びです。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Please refrain from such comments. It’s a maid’s honor to help her master."
L23_1.m_Talk_ENG = L24_1
L24_1 = "請不要這麼說，能為主人做事是我的榮幸。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "อย่าพูดอะไรแบบนั้นเลยค่ะ การได้ช่วยนายท่านคือเกียรติยศของเมดนะคะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Vui lòng hạn chế những bình luận như vậy. Đó là vinh dự của một hầu gái khi được giúp đỡ chủ nhân của mình."
L23_1.m_Talk_VTN = L24_1
L24_1 = "请不要这么说。能够成为主人的助力，就是女仆存在的意义。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Bitte nicht. Es ist die Ehre eines Hausmädchens, seinem Meister zu helfen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "S'il vous plaît, ne dites pas ça. C'est l'honneur d'une servante d'être utile à son maître."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "SUMMER2021_ACT1_PROLOGUE@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3200101
L24_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L25_1 = "LEADER_MAID_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "마침 메이드 일을 하면서 교류하게 된 분이 계시답니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ちょうどメイドの仕事中に出会い、交流している方がいます。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I happen to know this one person from my maid business."
L24_1.m_Talk_ENG = L25_1
L25_1 = "剛好我有在工作中認識一個人。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฉันบังเอิญรู้จักคนคนหนึ่งในวงการเมด"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi tình cờ biết một người trong dịch vụ hầu gái này."
L24_1.m_Talk_VTN = L25_1
L25_1 = "正好有个我做女仆工作时认识的人。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich kenne zufällig diese eine Person aus dem Geschäft der Hausmädchen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Il se trouve que je connais justement quelqu'un qui pourrait vous aider."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "SUMMER2021_ACT1_PROLOGUE@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3200101
L25_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L26_1 = "LEADER_MAID_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "그분이라면 분명 두 분을 만족스러운 휴양지로 안내해 주실 겁니다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "その方なら、お二人のお気に召されるリゾート地へ案内できると思います。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I’m sure she will lead you two to a vacation spot to your satisfaction."
L25_1.m_Talk_ENG = L26_1
L26_1 = "她應該可以介紹讓兩位都滿意的度假村。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ฉันมั่นใจว่าเธอจะพาคุณไปยังสถานที่พักผ่อนที่คุณพอใจได้ค่ะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi chắc rằng cô ấy sẽ dẫn hai người đến điểm nghỉ mát thỏa mãn yêu cầu."
L25_1.m_Talk_VTN = L26_1
L26_1 = "她会带您找到让二位满意的度假地。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich bin sicher, sie wird Sie beide zu Ihrer Zufriedenheit zu einem Urlaubsort führen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Je suis sûr qu'elle vous conduira tous les deux vers un lieu à la hauteur de vos espérances."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "SUMMER2021_ACT1_PROLOGUE@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3200101
L26_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "LEADER_MAID_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "지금 계신 곳을 알려 주시죠. 바로 연락하도록 하겠습니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "今いらっしゃる場所を教えてください。ただちに連絡を入れるよう手配いたします。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Please tell me where you are now. I’ll make the call right away."
L26_1.m_Talk_ENG = L27_1
L27_1 = "請告訴我您現在的位置，我會馬上跟您聯絡。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "บอกฉันเลยค่ะว่าตอนนี้คุณอยู่ที่ไหน แล้วฉันจะรีบโทรศัพท์ทันที"
L26_1.m_Talk_THA = L27_1
L27_1 = "Vui lòng nói cho tôi ngài đang ở đâu. Tôi sẽ gọi ngay bây giờ."
L26_1.m_Talk_VTN = L27_1
L27_1 = "请告诉我您现在的位置，我马上联系她。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Bitte sagen Sie mir, wo Sie jetzt sind. Ich rufe gleich an."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Pouvez-vous me donner votre position actuelle ? Je vais l'appeler tout de suite."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
