L29_1.m_Face = "UNIT_LAUGH"
L30_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "L"
L30_1 = "확실히 훌륭한 인재로군요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "確かに素晴らしい人材ですね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "She really is a special talent."
L29_1.m_Talk_ENG = L30_1
L30_1 = "果然是很優秀。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เธอคนนี้เป็นคนเก่งที่พิเศษมากค่ะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Cô ấy quả thực là một tài năng đặc biệt."
L29_1.m_Talk_VTN = L30_1
L30_1 = "确实是个优秀的人才呢。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Sie ist wirklich ein besonderes Talent."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Sacrée Veronica, on peut vraiment compter sur elle."
L29_1.m_Talk_FRA = L30_1
