L31_1 = "SUMMER2021_ACT1_PROLOGUE@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3200101
L30_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "L"
L31_1 = "세계를 수도 없이 말아먹은 누구와는 다르게 말이죠."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "世界を何度も崩壊させた誰かさんと違って。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Unlike someone who almost destroyed the world countless times."
L30_1.m_Talk_ENG = L31_1
L31_1 = "和老是惹麻煩的傢伙就是不一樣。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ไม่เหมือนใครบางคนที่เกือบทำลายโลกมาแล้วนับครั้งไม่ถ้วน"
L30_1.m_Talk_THA = L31_1
L31_1 = "Không giống người nào đó suýt phá hủy thế giới không biết bao nhiêu lần."
L30_1.m_Talk_VTN = L31_1
L31_1 = "跟无数次毁掉世界的某人就是不一样。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Im Gegensatz zu jemandem, der unzählige Male beinahe die Welt zerstört hätte."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Pas comme d'autres qui ont la mauvaise habitude d'amener le monde à sa ruine, encore et encore..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
