L33_1 = "SUMMER2021_ACT1_PROLOGUE@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3200101
L32_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L33_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "L"
L33_1 = "이럴 줄 알았으면 맨션 사건 때 어떻게든 정규직으로 고용해 둘 걸 그랬습니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "こうなると分かっていたら、マンション事件の時に何としてでも正社員として雇っておけばよかったです。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I should have hired her as a regular employee after the Mansion incident."
L32_1.m_Talk_ENG = L33_1
L33_1 = "早知如此，在曼森事件時，不管怎麼樣都要聘請她為正式員工才對。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฉันน่าจะจากเธอเป็นพนักงานประจำหลังเหตุการณ์เรื่องคฤหาสน์"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi đáng lẽ nên thuê cô ấy làm nhân viên chính thức sau sự cố Biệt Thự."
L32_1.m_Talk_VTN = L33_1
L33_1 = "早知道这样，曼森事件时我就该想办法雇佣她为正式职员。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich hätte sie nach dem Mansion-Vorfall als reguläre Angestellte einstellen sollen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "J'aurais dû l'embaucher comme employée régulière après l'incident du Manoir."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SUMMER2021_ACT1_PROLOGUE@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3200101
L33_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_LAUGH"
L34_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "R"
L34_1 = "하하, 급할수록 돌아가란 말도 있지 않나."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ハハハ、急がば回れという言葉もあるじゃないか。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Hah hah, there’s a saying, “Make haste slowly.”"
L33_1.m_Talk_ENG = L34_1
L34_1 = "哈哈，俗話不是說「吃緊弄破碗」嗎？ "
L33_1.m_Talk_TWN = L34_1
L34_1 = "ฮ่าๆ มีคำกล่าวที่ว่า “ช้าๆ ได้พร้าเล่มงาม” นะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Ha ha, có một câu nói thế này, “Đừng vội vàng.”"
L33_1.m_Talk_VTN = L34_1
L34_1 = "哈哈，心急吃不了热豆腐嘛。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Hah hah, es gibt ja das Sprichwort: „Gut Ding will Weile haben.“"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Ha ha, « hâtez-vous lentement », comme on dit."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "SUMMER2021_ACT1_PROLOGUE@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3200101
L34_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L34_1.m_bWaitClick = false
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_PRIDE"
L35_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "R"
L35_1 = "베로니카 양에게도 마음 정리할 시간이……"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ベロニカにも心を整理する時間が……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Veronica also needs some time to get herself sorted..."
L34_1.m_Talk_ENG = L35_1
L35_1 = "應該要給貝洛妮卡一些思考的時間…"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เวโรนิกาเองก็ต้องการเวลาเรียบเรียงความคิดเหมือนกัน"
L34_1.m_Talk_THA = L35_1
L35_1 = "Veronica cũng cần thời gian để sắp xếp mọi chuyện..."
L34_1.m_Talk_VTN = L35_1
L35_1 = "贝罗尼卡她也需要时间调整心情……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Auch Veronica braucht etwas Zeit, um sich zu entscheiden ..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Je suis sûr qu'elle aussi, elle aurait besoin de temps pour prendre sa décision..."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
