L38_1 = "FX_CUTSCEN_CAR_SKID"
L37_1.m_StartFXSoundName = L38_1
L38_1 = "LARA_NPC_DILIVER_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "비켜! 비켜비켜비켜비켜비켜비켜비켜비켜!!!"
L37_1.m_Talk_KOREA = L38_1
L38_1 = 0.02
L37_1.m_fTalkTime = L38_1
L38_1 = "どいてー！　どいてどいてどいてどいてどいてどいてどいてどいてー！！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Out of my way! Move! Move! Move!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "讓開！讓開讓開讓開讓開讓開讓開！！！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "หลีกทางหน่อย! เถิบ! เถิบ! เถิบ!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tránh đường! Tránh ra! Tránh ra! Tránh ra!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "让开！让开让开让开让开让开让开让开让开！"
L37_1.m_Talk_SCN = L38_1
