L41_1.m_Face = "UNIT_SERIOUS"
L42_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "L"
L42_1 = "괜찮으십니까, 사장님?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "大丈夫ですか？　社長！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Are you okay, Boss?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "老闆你沒事吧？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ไม่เป็นไรใช่มั้ยคะ บอส?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Anh có ổn không, Sếp?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "您没事吧，老板？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Sind Sie okay, Boss?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Tout va bien, Monsieur ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "SUMMER2021_ACT1_PROLOGUE@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3200101
L42_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "R"
L42_1.m_Crash = 20
L43_1 = "그, 그럼. 자네가 막아 준 덕분일세."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "な、なんとか。君が防いでくれたおかげだ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "S-sure, all thanks to you."
L42_1.m_Talk_ENG = L43_1
L43_1 = "當…當然，幸好有你擋著。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "นะ-แน่นอน เพราะคุณเลยละ"
L42_1.m_Talk_THA = L43_1
L43_1 = "C-chắc rồi, nhờ ơn cô cả."
L42_1.m_Talk_VTN = L43_1
L43_1 = "没、没事。多亏你挡了一下。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "S-sicher, alles dank Ihnen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oui, j-je crois. Grâce à toi."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "SUMMER2021_ACT1_PROLOGUE@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3200101
L43_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_DESPAIR"
L44_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "R"
L44_1 = "그리고 나보다는 자네랑 부딪쳐서 튕겨 나간 저 아가씨부터 걱정해야 할 것 같군."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ところで、私よりも君にぶつかって弾き飛ばされたあの女性を心配したほうがよさそうだ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I think you should worry about that girl, rather than me."
L43_1.m_Talk_ENG = L44_1
L44_1 = "而且我覺得那位撞到你後彈飛出去的小姐，好像更需要關心。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ผมว่าคุณควรเป็นห่วงผู้หญิงคนนั้นมากกว่าผมนะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi nghĩ cô nên lo cho cô ấy hơn là tôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "而且，比起我，似乎更应该担心被你撞飞的那位姑娘吧。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich denke, Sie sollten sich um dieses Mädchen Sorgen machen, anstatt um mich."
L43_1.m_Talk_DEU = L44_1
L44_1 = "C'est plutôt pour cette fille que tu devrais t'inquiéter, non ?"
L43_1.m_Talk_FRA = L44_1
