L47_1 = "SUMMER2021_ACT1_PROLOGUE@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3200101
L46_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_SURPRISE"
L47_1 = "LARA_NPC_DILIVER_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L46_1.m_Crash = 30
L47_1 = "죄송합니다! 목적지까지 서두르는 바람에 하마터면 다치게 할 뻔했네요!"
L46_1.m_Talk_KOREA = L47_1
L47_1 = 0.02
L46_1.m_fTalkTime = L47_1
L47_1 = "すみません！　あまりにも急いだせいで、危うく怪我をさせてしまうところでした！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "My apologies! I was in such a hurry, I almost hurt you!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "對不起！急著要趕到目的地差點害你受傷。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ขออภัยค่ะ! พอดีฉันรีบมากจนเกือบทำคุณบาดเจ็บ!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi xin lỗi! Tôi đang vội quá, suýt thì tôi làm cô bị thương rồi!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "对不起！因为我急着赶往目的地，差点儿害您受伤！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Entschuldigen Sie! Ich hatte es so eilig, dass ich Ihnen fast wehgetan hätte!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Je suis désolée !! J'étais si pressée que j'aurais pu vous blesser !"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "SUMMER2021_ACT1_PROLOGUE@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3200101
L47_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_LAUGH"
L48_1 = "LARA_NPC_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "전 플라티나 익스프레스의 라라 예거예요! 배달부죠!"
L47_1.m_Talk_KOREA = L48_1
L48_1 = 0.02
L47_1.m_fTalkTime = L48_1
L48_1 = "私はプラチナエクスプレスのララ・イェーガーです！　配達員です！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I’m Lara Jaeger from Platina Express! I’m a deliverywoman!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "我是白金運通的拉拉·伊格，是個送貨員！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันคือลารา เยเกอร์จากแพลตินาเอ็กซ์เพรส! ฉันเป็นพนักงานส่งของค่ะ!"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi là Lara Jaeger từ Platina Express! Tôi là shipper!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "我是普拉提娜快递服务的送货员！我叫拉拉·耶格！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich bin Lara Jaeger von Platina Express! Ich bin eine Lieferfrau!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Lara Jaeger, livreuse chez Platina Express, pour vous servir !"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "SUMMER2021_ACT1_PROLOGUE@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3200101
L48_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "LARA_NPC_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L48_1.m_Crash = 30
L49_1 = "이건 제 명함! 그럼 전 제 도움이 필요하다는 분이 계셔서 이만!"
L48_1.m_Talk_KOREA = L49_1
L49_1 = 0.02
L48_1.m_fTalkTime = L49_1
L49_1 = "これは私の名刺です！ では、自分の助けを必要としている方がいらっしゃるので、これで失礼します！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "This is my business card! There’s someone waiting for me, so I’ll be going now!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "這是我的名片！還有人在等我，先告辭囉！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "นี่นามบัตรฉันนะคะ! มีคนรอฉันอยู่ ดังนั้นขอตัวก่อนค่ะ!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đây là danh thiếp của tôi! Có người đang chờ, nên tôi phải đi luôn đây!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "这是我的名片！那我就先走了，有人还等着我帮忙哪！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Hier ist meine Visitenkarte! Jemand wartet auf mich, also gehe ich jetzt!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Tenez, voici ma carte de visite! Et maintenant je file, on m'attends !"
L48_1.m_Talk_FRA = L49_1
