L3_1 = "혹시 자네가 베로니카 양이 말한 사람인가? 우릴 휴양지로 데려다 준다던?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "もしかして君がベロニカが言っていた人か？　私たちをリゾート地まで連れてくれると聞いたが。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Are you the one Veronica told me about? The one who’s supposed to take us to the vacation spot?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "你是貝洛妮卡說的那個人嗎？你會帶我們到度假村？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "คุณคือคนที่เวโรนิกาพูดถึงรึเปล่าครับ? คนที่ต้องพาเราไปที่พักผ่อน?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Cô có phải người mà Veronica đã nói với tôi không? Người mà sẽ đưa chúng tôi đến nơi nghỉ mát?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "莫非你就是贝罗尼卡说的那个人？那个可以带我们找到理想度假地点的人选？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Sind Sie diejenige, von der Veronica mir erzählt hat? Die uns zum Urlaubsort bringen soll?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "C'est toi, le contact de Veronica ? Son amie qui est censé nous emmener à la plage ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "SUMMER2021_ACT1_PROLOGUE@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3200101
L3_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_SURPRISE"
L4_1 = "LARA_NPC_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L3_1.m_Crash = 30
L4_1 = "앗, 베로니카 씨랑 아는 사이셨어요?"
L3_1.m_Talk_KOREA = L4_1
L4_1 = 0.02
L3_1.m_fTalkTime = L4_1
L4_1 = "お、ベロニカさんのお知り合いだったんですね！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Oh, you know Veronica?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "咦，你認識貝洛妮卡嗎？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "อ้าว รู้จักเวโรนิกาเหรอคะ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ồ, anh biết Veronica à?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "唉？您也认识贝罗尼卡吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Kennen Sie Veronica?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Oh, vous connaissez Veronica ?"
L3_1.m_Talk_FRA = L4_1
