L5_1 = "SUMMER2021_ACT1_PROLOGUE@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3200101
L4_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L4_1.m_bWaitClick = false
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_LAUGH"
L5_1 = "LARA_NPC_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L4_1.m_Crash = 30
L5_1 = "정말 너무 좋은 분인 거 있죠? 제가 원래 24시간 가만히 있는 날이 없다 보니까 방 청소도 못하고 살았는데 때마침 그때!"
L4_1.m_Talk_KOREA = L5_1
L5_1 = 0.013
L4_1.m_fTalkTime = L5_1
L5_1 = "本当にいい方ですよね！　私ってあまり24時間部屋でゆっくりできる日がないからずっと部屋の掃除もまともにできなくて困っていた時があったんですけど、ちょうどタイミングよく！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "She’s such a good person! You see, I’m always on my way to deliver something, and I barely have any time to clean up my room. But then!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "她真的很棒對吧！我每天都忙於工作，根本沒時間打掃，但就在那個時候！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เธอเป็นคนดีมากเลยค่ะ! คืองี้ค่ะ ฉันต้องส่งของอยู่ตลอด และฉันก็แทบไม่มีเวลาเก็บกวาดห้องเลย แต่แล้วจู่ๆ!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Cô ấy là một người tốt! Anh thấy đấy, tôi luôn trên đường đi ship hàng, và tôi hiếm khi có thời gian để dọn dẹp phòng. Nhưng rồi!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "她人真的超好耶。因为我一天24小时都不会闲着，所以根本没时间打扫房间，就在那时！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Sie ist so ein guter Mensch! Sehen Sie, ich bin immer unterwegs, um etwas auszuliefern, und ich habe kaum Zeit, mein Zimmer aufzuräumen. Aber dann!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "C'est un ange, n'est-ce pas ? Comme je suis toujours en train de livrer quelque chose, je n'ai jamais le temps de ranger chez moi et ma chambre était toujours dans un état lamentable..."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "SUMMER2021_ACT1_PROLOGUE@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3200101
L5_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L5_1.m_bWaitClick = false
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_LAUGH"
L6_1 = "LARA_NPC_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L5_1.m_Crash = 30
L6_1 = "플로라 메이드 서비스의 전단지를 발견하고 연락을 드렸더니 하루만에 말끔히 치워 주시더라고요!"
L5_1.m_Talk_KOREA = L6_1
L6_1 = 0.013
L5_1.m_fTalkTime = L6_1
L6_1 = "フローラメイドサービスのチラシをみて連絡したら1日でキレイに片付けてくれました。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I found a Flora Maid Service flyer and called, and she cleaned up my room in just a single day!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "發現芙蘿拉女僕服務公司傳單，就嘗試聯繫一下，沒想到不到一天就幫我打掃得乾乾淨淨！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฉันก็เจอใบปลิวบริการเมดฟลอร่าและโทรไป เธอก็มาทำความสะอาดห้องให้ฉันเสร็จภายในวันเดียว!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tôi tìm thấy một tờ rơi của Dịch Vụ Người Hầu Hoa và gọi nó, và cô ấy đã dọn dẹp phòng tôi chỉ trong một ngày!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "我偶然发现了弗罗拉女仆服务的传单，于是便联系了她们，仅仅一天时间，她们就帮我全都收拾干净了！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Habe ich einen Flyer vom Hausmädchenservice Flora gefunden und angerufen, und sie hat mein Zimmer an nur einem einzigen Tag aufgeräumt!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Jusqu'au jour où je suis tombée sur ce dépliant du Service domestique Flora ! Un simple coup de fil, et hop ! Tout était rangé, plié, repassé."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "SUMMER2021_ACT1_PROLOGUE@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3200101
L6_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L6_1.m_bWaitClick = false
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_HATE"
L7_1 = "LARA_NPC_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L6_1.m_Crash = 30
L7_1 = "물론 며칠 못 가서 다시 어지럽히긴 했지만요."
L6_1.m_Talk_KOREA = L7_1
L7_1 = 0.013
L6_1.m_fTalkTime = L7_1
L7_1 = "もちろん数日経たずでまた散らかってしまいましたが……"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Well, the room got messy again after a few days though."
L6_1.m_Talk_ENG = L7_1
L7_1 = "當然才過沒幾天就又被我弄亂了。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แต่หลังจากผ่านไปสองสามวันห้องก็รกอีกนั่นละ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Chà, mặc dù căn phòng lại bừa bộn chỉ sau vài ngày."
L6_1.m_Talk_VTN = L7_1
L7_1 = "不过，没过几天就又被我弄乱了。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Na ja, nach ein paar Tagen war das Zimmer wieder unordentlich."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Bon, évidemment ça n'a pas duré..."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "SUMMER2021_ACT1_PROLOGUE@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3200101
L7_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L7_1.m_bWaitClick = false
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_LAUGH"
L8_1 = "LARA_NPC_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L7_1.m_Crash = 30
L8_1 = "그래도 진짜 깔끔하게 잘 정리해 주셔서 꼭 새로 입주한 집 같았는데 제가 지금처럼 워낙 정신없는 성격이라 눈 깜짝할 새 세상에 맙소사 난장판이 되는 거 있죠?"
L7_1.m_Talk_KOREA = L8_1
L8_1 = 0.013
L7_1.m_fTalkTime = L8_1
L8_1 = "でも本当にキレイに片付けまでしてくれたおかげでまるで新居のようになったんですが私ってさっきみたいにあまりにも落ち着きがない性格なのであっという間にめちゃくちゃになっちゃうんです。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "But still, when she cleaned up my room it was good as new, but I’m such a messy girl and oh my God my room went crazy like that in the blink of an eye!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "不過她真的幫我整理得很乾淨，乾淨到就像搬進新家一樣。看也知道我這個人神經很大條，所以房子瞬間就變成亂七八糟囉。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แต่ตอนที่เธอทำความสะอาดห้องฉัน มันดูเหมือนใหม่มากค่ะ แต่ฉันเป็นคนรก ทำให้ห้องฉันยุ่งเหยิงได้อีกครั้งภายในชั่วพริบตา!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Nhưng dù vậy, khi cô ấy dọn phòng, nó tốt như mới luôn, nhưng tôi là một người bừa bộn và Chúa ơi, phòng của tôi lại ngổn ngang chỉ trong nháy mắt!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "但是她们真的收拾得超整洁，让我有种搬新家的感觉。可惜的是我一直都是这种毛毛躁躁的性格，所以一眨眼的功夫——天啊，新家就又变成乱摊子了呢。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Aber trotzdem, als sie mein Zimmer aufgeräumt hat, war es so gut wie neu, aber ich bin so ein chaotisches Mädchen und oh mein Gott, mein Zimmer ist im Handumdrehen wieder ein Wirrwarr geworden!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Après son passage, c'était si propre que j'avais l'impression d'emménager dans une chambre neuve mais je suis tellement bordélique qu'en quelques jours à peine, c'était le chaos je vous raconte pas !"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "SUMMER2021_ACT1_PROLOGUE@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3200101
L8_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L8_1.m_bWaitClick = false
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_DESPAIR"
L9_1 = "LARA_NPC_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L8_1.m_Crash = 30
L9_1 = "흑흑. 그래서 베로니카 씨한테 싹싹 빌면서 한 번만 더 치워 줄 수 있냐고 부탁했더니 기꺼이 도와 주시더라고요."
L8_1.m_Talk_KOREA = L9_1
L9_1 = 0.013
L8_1.m_fTalkTime = L9_1
L9_1 = "ぐすん。だからベロニカさんに正座してもう一度片付けてほしいとお願いしたら快く助けてくれました。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "*Sob* So I begged Veronica to clean up my room just one more time, and she helped me again."
L8_1.m_Talk_ENG = L9_1
L9_1 = "嗚嗚，後來我就哀求貝洛妮卡再幫我打掃一次，她竟然欣然答應欸。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "*ฮือ* ฉันเลยขอให้เวโรนิกามาทำความสะอาดให้อีกครั้ง และเธอก็ยอมช่วยอีก"
L8_1.m_Talk_THA = L9_1
L9_1 = "*Nức nở* Nên tôi đã cầu xin Veronica dọn phòng tôi thêm một lần nữa, và cô ấy lại giúp tôi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "嘿嘿，没办法我就去求贝罗尼卡帮忙，让她再帮我收拾一遍，没想到她很痛快地就答应了。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "*Schluchz* Also habe ich Veronica angefleht, mein Zimmer noch einmal aufzuräumen, und sie hat mir wieder geholfen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "*Sanglot* Alors j'ai supplié Veronica de refaire le ménage dans ma chambre, et elle a accepté. Encore."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "SUMMER2021_ACT1_PROLOGUE@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3200101
L9_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L9_1.m_bWaitClick = false
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_SERIOUS"
L10_1 = "LARA_NPC_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L9_1.m_Crash = 30
L10_1 = "그 때 바로 촉이 팍 하고 꽂혔죠! 아, 이 사람은 믿을 수 있는 사람이다! 은혜를 원수로 갚지 말아야지!"
L9_1.m_Talk_KOREA = L10_1
L10_1 = 0.013
L9_1.m_fTalkTime = L10_1
L10_1 = "あの時ピンと来たのです！　あ、この人は信用できる人だと！　恩を仇で返すことはしない！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "That’s when I realized that she’s a trustworthy person and I simply must repay her kindness!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "那個時候就心想，這個人信得過！我一定要向她報恩！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ตอนนั้นฉันถึงรู้ว่าเธอเป็นคนที่เชื่อใจได้ และฉันต้องตอบแทนความใจดีของเธอค่ะ!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đó là lúc tôi nhận ra cô ấy là một người đáng tin và tôi chỉ đơn giản là phải báo đáp lòng tốt của cô ấy!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "那时候我就明白了！这个人是个可以信赖的！要好好地珍惜！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Da wurde mir klar, dass sie eine vertrauenswürdige Person ist und ich ihre Freundlichkeit einfach zurückzahlen muss!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "C'est là que j'ai compris qu'elle était vraiment digne de confiance ! Alors je peux bien lui rendre un service de temps en temps, hein ? C'est la moindre des choses !"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "SUMMER2021_ACT1_PROLOGUE@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3200101
L10_1.m_CutScenStrID = "SUMMER2021_ACT1_PROLOGUE"
L10_1.m_bWaitClick = false
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_LAUGH"
L10_1.m_bFadeIn = false
L10_1.m_fFadeTime = 2
L11_1 = "LARA_NPC_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L10_1.m_Crash = 30
L11_1 = "그렇게 굳게 다짐을 했다는 거 아니겠어요. 제가 워낙 배달을 여기저기 다니다 보니 사람 보는 눈은 좀 있다고 생각하는데요, 그렇다고 꼭 백발백중 들어맞는다는 뜻은 아닌데"
L10_1.m_Talk_KOREA = L11_1
L11_1 = 0.013
L10_1.m_fTalkTime = L11_1
L11_1 = "そうやって固く決心したわけです。私って仕事であちこち回っているから人を見る目は多少はある方だと思います。だからといって必ずしも百発百中当てはまるというわけではありませんが。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "That was my resolution. You see, I’ve been running around delivering goods, meeting a lot of people, and I know a good person when I see one, though that’s not a hundred percent guaranteed."
L10_1.m_Talk_ENG = L11_1
L11_1 = "任誰都會這麼想的嘛！我做外送這行看過的人也不少，還算是有點看人的眼光，當然也不是每次都很準啦。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "นั่นคือปณิธานของฉัน ฉันต้องเดินทางเพื่อส่งของตลอด ได้พบเจอผู้คนมากมาย และฉันดูออกว่าใครเป็นคนดีค่ะ แม้ว่าจะรับประกันไม่ได้ร้อยเปอร์เซ็นต์ก็ตาม"
L10_1.m_Talk_THA = L11_1
L11_1 = "Đó là cách của tôi. Anh thấy đấy, tôi đã chạy khắp nơi để giao hàng, gặp gỡ rất nhiều người và tôi biết ai là người tốt khi nhìn họ, mặc dù không phải một trăm phần trăm."
L10_1.m_Talk_VTN = L11_1
L11_1 = "……就这样，我下定了决心，因为我本来就在世界各地送快递，所以我感觉自己有些看人的眼光。虽然也不是每次都很准……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Das war mein Vorsatz. Sehen Sie, ich bin herumgelaufen, habe Waren geliefert, viele Leute getroffen, und ich erkenne eine gute Person, wenn ich eine sehe, obwohl das nicht hundertprozentig garantiert ist."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Vous savez, dans mon métier on en rencontre des gens alors je sais reconnaître une bonne personne quand j'en vois une. Enfin on est jamais certain de rien, bien sûr, mais Veronica elle, elle m'a tendu la main peut-être à un moment où je ne pouvais pas où j'étais seule chez m..."
L10_1.m_Talk_FRA = L11_1
